'use client';

import Script from 'next/script';
import { Fragment, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { MutableRefObject } from 'react';
import { effectiveProjectStageId, glossaryTermAppearsInTexts, hasChronologyChanges, type CatalogItem, type ContentRevision, type ExternalEntityLink, type ExternalLegislatorRecord, type ExternalSource, type GlossaryTerm, type Legislator, type LegislatorImportField, type LegislatorImportSuggestion, type OfficialDocument, type Project, type ProjectInput, type ProjectUpdate, type PublicProject, type RoleAssignment, type SiteSettings, type Source, type Subscription, type WorkflowDefinition } from '@politeia/quorum-contracts';
import { publicApiBase } from '@/lib/api';
import ProjectDetail from '@/components/ProjectDetail';
import { SiteFooter, SiteHeader } from '@/components/SiteChrome';
import QuorumRichTextEditor from '@/components/QuorumRichTextEditor';
import StageExplanationEditor, { ProjectStageExplanationEditor } from '@/components/StageExplanationEditor';
import { glossaryMatches, glossaryOccurrenceId } from '@/lib/glossary';
import { richTextPlainText } from '@/lib/richText';

type User = { email: string; name: string; picture: string; roles: Array<'quorum_editor' | 'quorum_admin'>; csrfToken: string };
type Audit = { id: string; type: string; actorEmail: string; targetId: string; createdAt: string; details?: Record<string, unknown> };
type Bootstrap = { projects: Project[]; catalogs: CatalogItem[]; workflows: WorkflowDefinition[]; settings: SiteSettings; legislators: Legislator[]; glossary: GlossaryTerm[]; subscriptions: Subscription[]; roles: RoleAssignment[]; audits: Audit[]; revisions: ContentRevision[] };
type IntegrationSource = ExternalSource & { freshness: 'fresh' | 'expiring' | 'due' | 'syncing' | 'attention'; pendingChanges: number };
type IntegrationOverview = { enabled: boolean; autoSyncEnabled: boolean; syncIntervalDays: number; sources: IntegrationSource[]; counts: { runs: number; snapshots: number; legislators: number; links: number; pendingChanges: number } };
type ExternalLegislatorSearchItem = { record: ExternalLegislatorRecord; link: ExternalEntityLink | null; possibleMatches: Array<Pick<Legislator, 'id' | 'fullName' | 'district' | 'bloc' | 'published'>> };
type Tab = 'tablero' | 'proyectos' | 'legisladores' | 'glosario' | 'catalogos' | 'seguidores' | 'configuracion' | 'usuarios' | 'historial';

declare global { interface Window { google?: { accounts: { id: { initialize: (options: Record<string, unknown>) => void; renderButton: (element: HTMLElement, options: Record<string, unknown>) => void } } } } }

const tabs: Array<{ id: Tab; label: string; admin?: boolean }> = [
  { id: 'tablero', label: 'Tablero' }, { id: 'proyectos', label: 'Proyectos' }, { id: 'legisladores', label: 'Legisladores' }, { id: 'glosario', label: 'Glosario' },
  { id: 'catalogos', label: 'Etapas y catálogos', admin: true }, { id: 'seguidores', label: 'Seguidores' }, { id: 'configuracion', label: 'Configuración', admin: true },
  { id: 'usuarios', label: 'Usuarios', admin: true }, { id: 'historial', label: 'Historial' },
];

export default function ManagementApp() {
  const [user, setUser] = useState<User | null>(null); const [data, setData] = useState<Bootstrap | null>(null); const [tab, setTab] = useState<Tab>('tablero');
  const [busy, setBusy] = useState(true); const [message, setMessage] = useState('');
  const admin = user?.roles.includes('quorum_admin') === true;

  const call = useCallback(async (path: string, init: RequestInit = {}) => {
    const headers = new Headers(init.headers); if (user?.csrfToken && !['GET', 'HEAD'].includes(init.method || 'GET')) headers.set('x-csrf-token', user.csrfToken);
    let response: Response;
    try { response = await fetch(`${publicApiBase}${path}`, { ...init, headers, credentials: 'include' }); }
    catch { throw new Error('No pudimos conectarnos con la API de Quórum. Verificá que el backend local esté encendido.'); }
    const body = response.status === 204 ? null : await response.json().catch(() => null);
    if (!response.ok) {
      const message = body?.error?.message || `La API rechazó la operación (HTTP ${response.status}).`;
      throw new Error(body?.error?.requestId ? `${message} · referencia ${body.error.requestId}` : message);
    }
    return body;
  }, [user]);

  const reload = useCallback(async () => { const body = await call('/v1/manage/bootstrap'); setData(body); }, [call]);

  useEffect(() => { void (async () => { try { const response = await fetch(`${publicApiBase}/v1/me`, { credentials: 'include' }); if (!response.ok) return; const body = await response.json(); setUser(body.user); } finally { setBusy(false); } })(); }, []);
  useEffect(() => { if (!user?.roles.length) return; setBusy(true); reload().catch((error) => setMessage(error.message)).finally(() => setBusy(false)); }, [user, reload]);

  async function googleLogin(credential: string) { setBusy(true); setMessage(''); try { const response = await fetch(`${publicApiBase}/v1/auth/google`, { method: 'POST', headers: { 'content-type': 'application/json' }, credentials: 'include', body: JSON.stringify({ credential }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error?.message); setUser(body.user); } catch (error) { setMessage(error instanceof Error ? error.message : 'No pudimos iniciar sesión.'); } finally { setBusy(false); } }
  function renderGoogleButton() { const target = document.getElementById('google-login'); if (!target || !window.google || !process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID) return; window.google.accounts.id.initialize({ client_id: process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID, callback: ({ credential }: { credential: string }) => void googleLogin(credential) }); window.google.accounts.id.renderButton(target, { theme: 'outline', size: 'large', text: 'signin_with', locale: 'es' }); }
  async function logout() { await call('/v1/auth/logout', { method: 'POST' }); setUser(null); setData(null); }

  if (!user) return <section className="management-login"><Script src="https://accounts.google.com/gsi/client" strategy="afterInteractive" onLoad={renderGoogleButton} /><div className="login-card"><span className="wordmark"><strong>Quórum</strong><span>Gestión</span></span><h1>Espacio editorial seguro</h1><p>Ingresá con una cuenta autorizada. Los borradores permanecen separados de la experiencia pública hasta que decidas publicarlos.</p><div id="google-login" />{!process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID && <p className="message">En desarrollo local, iniciá la API con <code>DEV_AUTH=true</code> y recargá esta página.</p>}{message && <p className="message error">{message}</p>}</div></section>;
  if (!user.roles.length) return <section className="management-login"><div className="login-card"><span className="eyebrow">Gestión Quórum</span><h1>Acceso sólo de lectura</h1><p>Esta cuenta puede participar de la prueba privada, pero no tiene un rol editorial asignado. Un administrador debe incorporarla desde Usuarios para habilitar el gestor.</p><button className="button dark" type="button" onClick={logout}>Cerrar sesión</button></div></section>;
  if (busy || !data) return <section className="management-login"><div className="login-card"><span className="eyebrow">Gestión Quórum</span><h2>Cargando espacio editorial…</h2></div></section>;

  const visibleTabs = tabs.filter((item) => !item.admin || admin);
  return <div className="management-shell"><aside className="management-nav"><div className="wordmark"><strong>Quórum</strong><span>Gestión</span></div><nav>{visibleTabs.map((item) => <button key={item.id} className={tab === item.id ? 'active' : ''} onClick={() => setTab(item.id)}>{item.label}</button>)}</nav><div className="manager-user"><strong>{user.name}</strong><span>{user.email}</span><button onClick={logout}>Cerrar sesión</button></div></aside><section className="management-content"><header className="management-top"><div><span className="eyebrow">Gestión editorial</span><h1>{visibleTabs.find((item) => item.id === tab)?.label}</h1></div><span className="environment-pill">Entorno: {process.env.NEXT_PUBLIC_ENVIRONMENT || 'local'}</span></header>{message && <p className="message" role="status">{message}</p>}{tab === 'tablero' && <Dashboard data={data} />}{tab === 'proyectos' && <Projects data={data} call={call} reload={reload} notify={setMessage} />}{tab === 'legisladores' && <Legislators data={data} call={call} reload={reload} notify={setMessage} admin={admin} />}{tab === 'glosario' && <Glossary data={data} call={call} reload={reload} notify={setMessage} />}{tab === 'catalogos' && <Catalogs data={data} call={call} reload={reload} notify={setMessage} />}{tab === 'seguidores' && <Followers data={data} />}{tab === 'configuracion' && <Settings data={data} call={call} reload={reload} notify={setMessage} />}{tab === 'usuarios' && <Users data={data} call={call} reload={reload} notify={setMessage} />}{tab === 'historial' && <History data={data} call={call} reload={reload} notify={setMessage} admin={admin} />}</section></div>;
}

function Dashboard({ data }: { data: Bootstrap }) {
  const published = data.projects.filter((item) => item.status === 'published').length;
  return <><div className="stat-grid"><Stat label="Borradores" value={data.projects.filter((item) => item.status === 'draft').length} /><Stat label="Publicados" value={published} /><Stat label="Seguidores activos" value={data.subscriptions.filter((item) => item.status === 'active').length} /><Stat label="Revisiones" value={data.revisions.length} /></div><section className="admin-panel"><h2>Estado de salida</h2><div className="readiness-list"><Check ok={data.projects.length >= 6} label="Borradores iniciales creados" /><Check ok={data.settings.privacyPolicyApproved} label="Política de privacidad aprobada" /><Check ok={data.settings.subscriptionsEnabled} label="Correo de seguimiento habilitado" /><Check ok={published > 0} label="Contenido validado y publicado" /></div></section></>;
}
function Stat({ label, value }: { label: string; value: number }) { return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>; }
function Check({ ok, label }: { ok: boolean; label: string }) { return <div className="readiness-item"><span className={ok ? 'ok' : ''}>{ok ? '✓' : '○'}</span>{label}</div>; }

type AdminProps = { data: Bootstrap; call: (path: string, init?: RequestInit) => Promise<any>; reload: () => Promise<void>; notify: (value: string) => void };

function Projects({ data, call, reload, notify }: AdminProps) {
  const [selectedId, setSelectedId] = useState(data.projects[0]?.id || 'new');
  const [editorDirty, setEditorDirty] = useState(false);
  const [pendingSelection, setPendingSelection] = useState<string | null>(null);
  const [switching, setSwitching] = useState(false);
  const [switchError, setSwitchError] = useState('');
  const editorHandle = useRef<{ save: () => Promise<boolean> } | null>(null);
  const selected = data.projects.find((item) => item.id === selectedId);
  function select(nextId: string) { if (nextId === selectedId) return; if (editorDirty) { setSwitchError(''); setPendingSelection(nextId); } else setSelectedId(nextId); }
  function discardAndSwitch() { if (!pendingSelection) return; setSelectedId(pendingSelection); setPendingSelection(null); setSwitchError(''); setEditorDirty(false); }
  async function saveAndSwitch() { if (!pendingSelection || !editorHandle.current) return; setSwitchError(''); setSwitching(true); const saved = await editorHandle.current.save(); setSwitching(false); if (!saved) { setSwitchError('No pudimos guardar el proyecto. Seguí editando y corregí los campos indicados antes de cambiar.'); return; } setSelectedId(pendingSelection); setPendingSelection(null); setEditorDirty(false); }
  return <><div className="admin-split"><section className="admin-list"><button className="button primary full" onClick={() => select('new')}>Nuevo proyecto</button>{data.projects.map((item) => <button key={item.id} className={item.id === selectedId ? 'selected' : ''} onClick={() => select(item.id)}><strong>{item.title}</strong><span>{statusLabel(item.status)} · {item.docketNumber || 'Sin expediente'}</span></button>)}</section><ProjectEditor key={selected?.id || 'new'} project={selected} data={data} call={call} reload={reload} notify={notify} onCreated={setSelectedId} editorHandle={editorHandle} onDirtyChange={setEditorDirty} /></div>{pendingSelection && <div className="dialog-backdrop" onMouseDown={() => { if (!switching) { setPendingSelection(null); setSwitchError(''); } }}><section className="dialog warning-dialog" role="alertdialog" aria-labelledby="unsaved-title" aria-describedby="unsaved-description" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Cambios sin guardar</span><h2 id="unsaved-title">¿Querés salir de este proyecto?</h2><p id="unsaved-description">Los cambios que hiciste en esta pantalla todavía no se guardaron. Si continuás sin guardar, se van a perder.</p>{switchError && <p className="message error" role="alert">{switchError}</p>}<div className="dialog-actions three-actions"><button className="button ghost" disabled={switching} onClick={() => { setPendingSelection(null); setSwitchError(''); }}>Seguir editando</button><button className="button danger" disabled={switching} onClick={discardAndSwitch}>Descartar y cambiar</button><button className="button primary" disabled={switching} onClick={() => void saveAndSwitch()}>{switching ? 'Guardando…' : 'Guardar y cambiar'}</button></div></section></div>}</>;
}

function ProjectEditor({ project, data, call, reload, notify, onCreated, editorHandle, onDirtyChange }: AdminProps & { project?: Project; onCreated: (id: string) => void; editorHandle: MutableRefObject<{ save: () => Promise<boolean> } | null>; onDirtyChange: (dirty: boolean) => void }) {
  const workflow = data.workflows.find((item) => item.id === project?.workflowId) || data.workflows.find((item) => item.active) || data.workflows[0];
  const [form, setForm] = useState<ProjectInput>(() => project ? projectToInput(project) : emptyProject(workflow));
  const [preview, setPreview] = useState(false); const [publish, setPublish] = useState(false); const [publishGate, setPublishGate] = useState<'unsaved' | 'blocked' | null>(null); const [publishGateError, setPublishGateError] = useState(''); const [saving, setSaving] = useState(false); const [savingChronology, setSavingChronology] = useState(false);
  const [projectAction, setProjectAction] = useState<'unpublish' | 'archive' | null>(null); const [projectActionBusy, setProjectActionBusy] = useState(false); const [projectActionError, setProjectActionError] = useState('');
  const storedForm = project ? projectToInput(project) : emptyProject(workflow);
  const revisions = data.revisions.filter((item) => item.projectId === project?.id).sort((a, b) => b.number - a.number);
  const latestRevision = revisions[0];
  const publishedForm = latestRevision ? projectToInput(latestRevision.snapshot) : null;
  const isDirty = !sameValue(form, storedForm);
  const chronologyDirty = !sameValue(form.updates || [], project?.updates || []);
  const savedChangesPending = Boolean(project && (!publishedForm || !sameValue(storedForm, publishedForm)));
  const onlyChronologyPending = Boolean(publishedForm && !sameValue(storedForm.updates || [], publishedForm.updates || []) && sameValue(withoutUpdates(storedForm), withoutUpdates(publishedForm)));
  const chronologyChanged = hasChronologyChanges(form, publishedForm);
  const publicationIssues = project ? getPublicationIssues(project, form, false, isDirty || savedChangesPending, data) : [];
  const canPublish = Boolean(project && !isDirty && publicationIssues.length === 0);
  const stageChanged = Boolean(latestRevision && effectiveProjectStageId(latestRevision.snapshot) !== effectiveProjectStageId({ currentStageId: form.currentStageId, updates: form.updates || [] }));
  const set = (key: keyof ProjectInput, value: unknown) => setForm((current) => ({ ...current, [key]: value }));
  async function save(): Promise<boolean> {
    if (!isDirty || saving) return !isDirty;
    setSaving(true);
    try {
      const body = await call(project ? `/v1/manage/projects/${project.id}` : '/v1/manage/projects', { method: project ? 'PATCH' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) });
      setForm(projectToInput(body.item));
      notify('Borrador guardado. Los cambios todavía no son públicos.');
      await reload();
      if (!project) onCreated(body.item.id);
      return true;
    } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos guardar.'); return false; }
    finally { setSaving(false); }
  }
  editorHandle.current = { save };
  useEffect(() => { onDirtyChange(isDirty); return () => onDirtyChange(false); }, [isDirty, onDirtyChange]);
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (!isDirty) return; event.preventDefault(); event.returnValue = ''; }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn); }, [isDirty]);
  async function saveChronology() {
    if (!project || !chronologyDirty || savingChronology) return;
    setSavingChronology(true);
    try {
      const body = await call(`/v1/manage/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ updates: form.updates || [] }) });
      setForm((current) => ({ ...current, updates: body.item.updates }));
      notify('Cronología guardada en el borrador. Publicá la revisión desde el sector global cuando esté aprobada.');
      await reload();
    } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos guardar la cronología.'); }
    finally { setSavingChronology(false); }
  }
  async function uploadEditorImage(file: File) { return uploadRichImage(call, file); }
  function requestPublication() {
    setPublishGateError('');
    if (publicationIssues.length) { setPublishGate('blocked'); return; }
    if (isDirty) { setPublishGate('unsaved'); return; }
    setPublish(true);
  }
  async function saveAndOpenPublication() {
    setPublishGateError('');
    const saved = await save();
    if (!saved) { setPublishGateError('No pudimos guardar el borrador. Revisá el mensaje de error y volvé a intentarlo.'); return; }
    setPublishGate(null); setPublish(true);
  }
  function requestProjectAction(action: 'unpublish' | 'archive') {
    setProjectActionError('');
    setProjectAction(action);
  }
  async function confirmProjectAction() {
    if (!project || !projectAction || projectActionBusy) return;
    setProjectActionBusy(true);
    setProjectActionError('');
    try {
      await call(`/v1/manage/projects/${project.id}/${projectAction}`, { method: 'POST' });
      notify(projectAction === 'unpublish' ? 'Proyecto despublicado. El borrador y su historial se conservaron.' : 'Proyecto archivado. El contenido y su historial se conservaron.');
      setProjectAction(null);
      await reload();
    } catch (error) {
      setProjectActionError(error instanceof Error ? error.message : `No pudimos ${projectAction === 'unpublish' ? 'despublicar' : 'archivar'} el proyecto.`);
    } finally {
      setProjectActionBusy(false);
    }
  }
  if (!workflow) return <section className="admin-panel"><h2>Falta un flujo activo</h2><p>Creá o activá una definición de etapas antes de dar de alta proyectos.</p></section>;
  return <section className="admin-panel editor-form">
    <div className="panel-title"><div><div className="status-line"><span className="status-pill">{project ? statusLabel(project.status) : 'Nuevo borrador'}</span>{isDirty && <span className="unsaved-pill">Cambios sin guardar</span>}</div><h2>{project?.title || 'Nuevo proyecto'}</h2></div><div className="editor-actions"><button className="button ghost" onClick={() => setPreview(true)} disabled={!project}>Previsualizar</button><button className="button primary" onClick={save} disabled={!isDirty || saving || savingChronology}>{saving ? 'Guardando…' : 'Guardar'}</button></div></div>
    <div className="form-grid"><Field label="Título"><input value={form.title} onChange={(e) => { set('title', e.target.value); if (!project) set('slug', slugify(e.target.value)); }} /></Field><Field label="Slug estable"><input value={form.slug} onChange={(e) => set('slug', slugify(e.target.value))} disabled={Boolean(project?.publishedAt)} /></Field><Field label="Expediente"><input value={form.docketNumber || ''} onChange={(e) => set('docketNumber', e.target.value)} /></Field><Field label="Fecha de ingreso"><input type="date" value={form.entryDate || ''} onChange={(e) => set('entryDate', e.target.value || null)} /></Field><Field label="Cámara de origen"><select value={form.originChamberId || ''} onChange={(e) => set('originChamberId', e.target.value || null)}><option value="">Seleccionar</option>{data.catalogs.filter((item) => item.kind === 'chamber' && item.active).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></Field><Field label="Iniciativa"><select value={form.initiativeTypeId || ''} onChange={(e) => set('initiativeTypeId', e.target.value || null)}><option value="">Seleccionar</option>{data.catalogs.filter((item) => item.kind === 'initiative' && item.active).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></Field><Field label="Etapa inicial o histórica"><select value={form.currentStageId} onChange={(e) => set('currentStageId', e.target.value)}>{workflow.stages.filter((item) => item.active).sort((a, b) => a.order - b.order).map((item) => <option key={item.id} value={item.id}>{item.label}{item.branchFromId ? ' (rama)' : ''}</option>)}</select></Field><SingleLegislatorPicker items={data.legislators} value={form.authorLegislatorId || null} onChange={(value) => set('authorLegislatorId', value)} /></div>
    <ProjectStageExplanationEditor workflow={workflow} chamber={data.catalogs.find((item) => item.id === form.originChamberId) || null} initiative={data.catalogs.find((item) => item.id === form.initiativeTypeId) || null} globalExplanations={data.settings.legislativeStageExplanations} value={form.stageExplanationOverrides || []} onChange={(value) => set('stageExplanationOverrides', value)} />
    <AdvancedTextField label="Resumen en lenguaje claro" value={form.summary || ''} format={form.summaryFormat} onChange={(value) => set('summary', value)} onFormatChange={(value) => set('summaryFormat', value)} onUploadImage={uploadEditorImage} />
    <AdvancedTextField label="¿Cómo me afecta?" value={form.impact || ''} format={form.impactFormat} onChange={(value) => set('impact', value)} onFormatChange={(value) => set('impactFormat', value)} onUploadImage={uploadEditorImage} />
    <ProjectGlossarySettings terms={data.glossary} form={form} enabled={form.glossaryEnabled !== false} excludedIds={form.glossaryExcludedTermIds || []} occurrenceMode={form.glossaryOccurrenceMode || 'all'} excludedOccurrenceIds={form.glossaryExcludedOccurrenceIds || []} onEnabledChange={(value) => set('glossaryEnabled', value)} onExcludedChange={(value) => set('glossaryExcludedTermIds', value)} onOccurrenceModeChange={(value) => set('glossaryOccurrenceMode', value)} onExcludedOccurrenceChange={(value) => set('glossaryExcludedOccurrenceIds', value)} />
    <LegislatorRelationPicker items={data.legislators} selected={form.signatoryIds || []} onChange={(items) => set('signatoryIds', items)} />
    <SourcesEditor items={form.sources || []} onChange={(items) => set('sources', items)} />
    <DocumentsEditor items={form.documents || []} onChange={(items) => set('documents', items)} project={project} call={call} notify={notify} />
    <UpdatesEditor items={form.updates || []} publishedItems={publishedForm?.updates || []} onChange={(items) => set('updates', items)} workflow={workflow} canSave={Boolean(project && chronologyDirty)} saving={savingChronology} onSave={saveChronology} />
    <label className="check-row"><input type="checkbox" checked={form.featured || false} onChange={(e) => set('featured', e.target.checked)} /><span>Destacar este proyecto en la exploración pública</span></label>
    {project && <><div className={`publication-guidance ${canPublish || (isDirty && publicationIssues.length === 0) ? 'ready' : ''}`} role="status"><strong>{isDirty && publicationIssues.length === 0 ? 'Podés guardar y publicar en un solo paso' : canPublish ? 'La revisión está lista para publicar' : 'La publicación necesita atención'}</strong>{isDirty && publicationIssues.length === 0 ? <p>Al elegir “Publicar revisión” vas a confirmar primero el guardado de estos cambios.</p> : canPublish ? <p>Vas a poder revisar la notificación y confirmar la publicación en el paso siguiente.</p> : <ul>{publicationIssues.map((issue) => <li key={issue}>{issue}</li>)}</ul>}</div><div className="publish-row"><div className={`publication-state ${isDirty || savedChangesPending ? 'pending' : ''}`}><strong>{isDirty ? 'Cambios sin guardar' : onlyChronologyPending ? 'Cronología guardada' : savedChangesPending ? 'Cambios guardados' : 'Sin cambios pendientes'}</strong><span>{isDirty ? 'Podés guardarlos y continuar con la publicación desde el mismo flujo.' : savedChangesPending ? 'Pendiente de aprobación y publicación.' : 'La versión pública coincide con el borrador guardado.'}</span></div><button className="button dark" onClick={requestPublication} disabled={saving || savingChronology || projectActionBusy} aria-describedby="publication-feedback">{saving ? 'Guardando…' : 'Publicar revisión'}</button>{project.status === 'published' && <button className="button warning" type="button" disabled={projectActionBusy} onClick={() => requestProjectAction('unpublish')}>Despublicar</button>}{project.status !== 'archived' && <button className="button danger" type="button" disabled={projectActionBusy} onClick={() => requestProjectAction('archive')}>Archivar</button>}</div><span id="publication-feedback" className="sr-only">{isDirty && publicationIssues.length === 0 ? 'Hay cambios sin guardar. Podés guardarlos y continuar con la publicación.' : canPublish ? 'La revisión está lista para publicar' : publicationIssues.join('. ')}</span></>}
    {publishGate === 'unsaved' && <div className="dialog-backdrop" onMouseDown={() => !saving && setPublishGate(null)}><section className="dialog warning-dialog" role="alertdialog" aria-modal="true" aria-labelledby="publish-unsaved-title" aria-describedby="publish-unsaved-description" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Cambios sin guardar</span><h2 id="publish-unsaved-title">¿Guardar y preparar la publicación?</h2><p id="publish-unsaved-description">La publicación debe usar la versión que estás viendo. Primero guardaremos todos los cambios de esta pantalla y, si el guardado termina correctamente, podrás revisar y confirmar la nueva revisión pública.</p>{publishGateError && <p className="message error" role="alert">{publishGateError}</p>}<div className="dialog-actions"><button className="button ghost" type="button" disabled={saving} onClick={() => setPublishGate(null)}>Cancelar</button><button className="button primary" type="button" disabled={saving} onClick={() => void saveAndOpenPublication()}>{saving ? 'Guardando…' : 'Guardar y publicar'}</button></div></section></div>}
    {publishGate === 'blocked' && <div className="dialog-backdrop" onMouseDown={() => setPublishGate(null)}><section className="dialog warning-dialog" role="alertdialog" aria-modal="true" aria-labelledby="publish-blocked-title" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Antes de publicar</span><h2 id="publish-blocked-title">Faltan datos para publicar</h2><p>Corregí estos puntos en el proyecto y volvé a elegir “Publicar revisión”:</p><ul className="publication-blockers">{publicationIssues.map((issue) => <li key={issue}>{issue}</li>)}</ul><div className="dialog-actions"><button className="button primary" type="button" onClick={() => setPublishGate(null)}>Volver a editar</button></div></section></div>}
    {projectAction && project && <div className="dialog-backdrop" onMouseDown={() => { if (!projectActionBusy) setProjectAction(null); }}><section className={`dialog warning-dialog project-action-dialog ${projectAction}`} role="alertdialog" aria-modal="true" aria-labelledby="project-action-title" aria-describedby="project-action-description" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Confirmación requerida</span><h2 id="project-action-title">¿{projectAction === 'unpublish' ? 'Despublicar' : 'Archivar'} {project.title}?</h2><div className="confirmation-card"><strong>{projectAction === 'unpublish' ? 'La ficha dejará de estar disponible públicamente' : 'El proyecto saldrá del circuito activo'}</strong><p id="project-action-description">{projectAction === 'unpublish' ? 'Se retirará inmediatamente de la web pública. El borrador, los archivos y el historial de revisiones se conservarán para poder trabajar y publicarlo nuevamente.' : 'Se retirará inmediatamente de la web pública y quedará marcado como archivado. No se eliminarán el contenido, los archivos ni el historial editorial.'}</p></div>{projectActionError && <p className="message error" role="alert">{projectActionError}</p>}<div className="dialog-actions"><button className="button ghost" type="button" disabled={projectActionBusy} onClick={() => setProjectAction(null)}>Cancelar</button><button className={projectAction === 'unpublish' ? 'button warning' : 'button danger'} type="button" disabled={projectActionBusy} onClick={() => void confirmProjectAction()}>{projectActionBusy ? 'Procesando…' : projectAction === 'unpublish' ? 'Sí, despublicar' : 'Sí, archivar'}</button></div></section></div>}
    {preview && project && <PreviewDialog project={project} form={form} settings={data.settings} call={call} close={() => setPreview(false)} />}{publish && project && <PublishDialog project={project} canNotifyFollowers={chronologyChanged} suggestedNotify={stageChanged} call={call} reload={reload} notify={notify} close={() => setPublish(false)} />}
  </section>;
}

type LegislatorFilters = { query: string; office: string; district: string; party: string; bloc: string };
const emptyLegislatorFilters: LegislatorFilters = { query: '', office: '', district: '', party: '', bloc: '' };

function SingleLegislatorPicker({ items, value, onChange }: { items: Legislator[]; value: string | null; onChange: (id: string | null) => void }) {
  const [open, setOpen] = useState(false); const [filters, setFilters] = useState<LegislatorFilters>(emptyLegislatorFilters);
  const selected = items.find((item) => item.id === value) || null; const filtered = useMemo(() => filterLegislators(items, filters), [filters, items]);
  const groups = groupLegislators(filtered);
  return <div className="field single-legislator-picker"><span>Autoría</span><button className="legislator-select-trigger" type="button" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen((current) => !current)}><span>{selected?.fullName || 'Sin asignar'}</span><small>{selected ? `${officeLabel(selected.office)} · ${selected.district || 'Sin distrito'}` : 'Elegir legislador/a'}</small></button>{open && <div className="legislator-picker-popover"><LegislatorFilterControls items={items} filters={filters} onChange={setFilters} /><div className="legislator-picker-summary"><span><strong>{filtered.length}</strong> resultados</span>{hasLegislatorFilters(filters) && <button className="button ghost" type="button" onClick={() => setFilters(emptyLegislatorFilters)}>Limpiar</button>}</div><div className="legislator-options" role="listbox" aria-label="Elegir autoría"><button className={!value ? 'selected' : ''} type="button" role="option" aria-selected={!value} onClick={() => { onChange(null); setOpen(false); }}><strong>Sin asignar</strong></button>{groups.map((group) => <section key={group.key}><h4>{group.label} <span>{group.items.length}</span></h4>{group.items.map((item) => <button className={item.id === value ? 'selected' : ''} type="button" role="option" aria-selected={item.id === value} onClick={() => { onChange(item.id); setOpen(false); }} key={item.id}><strong>{item.fullName}</strong><small>{item.district || 'Sin distrito'} · {item.bloc || item.party || 'Sin bloque'}</small></button>)}</section>)}</div></div>}</div>;
}

function LegislatorRelationPicker({ items, selected, onChange }: { items: Legislator[]; selected: string[]; onChange: (ids: string[]) => void }) {
  const [filters, setFilters] = useState<LegislatorFilters>(emptyLegislatorFilters); const [onlySelected, setOnlySelected] = useState(false);
  const selectedSet = useMemo(() => new Set(selected), [selected]);
  const visible = useMemo(() => filterLegislators(items, filters), [filters, items]);
  const displayed = useMemo(() => visible.filter((item) => !onlySelected || selectedSet.has(item.id)), [onlySelected, selectedSet, visible]);
  const groups = groupLegislators(displayed);
  const visibleIds = visible.map((item) => item.id);
  const selectedVisibleCount = visibleIds.filter((id) => selectedSet.has(id)).length;
  const fullBloc = filters.bloc ? items.filter((item) => item.bloc === filters.bloc) : [];
  const selectedFullBlocCount = fullBloc.filter((item) => selectedSet.has(item.id)).length;
  const addIds = (ids: string[]) => onChange([...new Set([...selected, ...ids])]);
  const removeIds = (ids: string[]) => { const removed = new Set(ids); onChange(selected.filter((id) => !removed.has(id))); };
  return <fieldset className="relation-picker legislator-relation-picker"><legend>Firmantes</legend><LegislatorFilterControls items={items} filters={filters} onChange={setFilters} />
    <div className="legislator-bulk-actions"><div><strong>Selección rápida</strong><span>Las acciones respetan los filtros activos, salvo “bloque completo”.</span></div><div><button className="button ghost compact" type="button" disabled={!visibleIds.length || selectedVisibleCount === visibleIds.length} onClick={() => addIds(visibleIds)}>Seleccionar todos los visibles ({visibleIds.length})</button><button className="button ghost compact" type="button" disabled={!selectedVisibleCount} onClick={() => removeIds(visibleIds)}>Quitar selección visible ({selectedVisibleCount})</button>{filters.bloc && <button className="button primary compact" type="button" disabled={!fullBloc.length || selectedFullBlocCount === fullBloc.length} onClick={() => addIds(fullBloc.map((item) => item.id))}>Seleccionar bloque completo ({fullBloc.length})</button>}</div></div>
    <div className="legislator-picker-summary"><span><strong>{selected.length}</strong> seleccionados · <strong>{visible.length}</strong> coincidencias válidas</span><div><label className="check-row"><input type="checkbox" checked={onlySelected} onChange={(event) => setOnlySelected(event.target.checked)} /><span>Mostrar sólo seleccionados</span></label>{hasLegislatorFilters(filters) && <button className="button ghost" type="button" onClick={() => setFilters(emptyLegislatorFilters)}>Limpiar filtros</button>}</div></div><div className="legislator-choice-groups">{groups.length ? groups.map((group) => <details open key={group.key}><summary>{group.label}<span>{group.items.length}</span></summary><div>{group.items.map((item) => <label className="legislator-choice" key={item.id}><input type="checkbox" checked={selectedSet.has(item.id)} onChange={(event) => onChange(event.target.checked ? [...new Set([...selected, item.id])] : selected.filter((id) => id !== item.id))} /><span><strong>{item.fullName}</strong><small>{item.district || 'Sin distrito'} · {item.bloc || item.party || 'Sin bloque'}</small></span></label>)}</div></details>) : <div className="empty-state"><strong>{onlySelected && visible.length ? 'No hay personas seleccionadas entre las coincidencias.' : 'No hay legisladores para esos filtros.'}</strong><span>{onlySelected ? 'Desactivá “Mostrar sólo seleccionados” para volver a ver las opciones válidas.' : 'Las combinaciones sin coincidencias se bloquean en los filtros.'}</span></div>}</div></fieldset>;
}

function LegislatorFilterControls({ items, filters, onChange }: { items: Legislator[]; filters: LegislatorFilters; onChange: (filters: LegislatorFilters) => void }) {
  const facets = useMemo(() => ({
    offices: legislatorFacetOptions(items, filters, 'office', ['diputado', 'senador', 'otro']),
    districts: legislatorFacetOptions(items, filters, 'district', uniqueLegislatorValues(items, 'district')),
    parties: legislatorFacetOptions(items, filters, 'party', uniqueLegislatorValues(items, 'party')),
    blocs: legislatorFacetOptions(items, filters, 'bloc', uniqueLegislatorValues(items, 'bloc')),
  }), [filters, items]);
  const set = (key: keyof LegislatorFilters, value: string) => onChange({ ...filters, [key]: value });
  return <div className="legislator-filter-controls"><Field label="Buscar"><input type="search" value={filters.query} onChange={(event) => set('query', event.target.value)} placeholder="Nombre, partido, bloque o distrito" /></Field><Field label="Cámara"><select value={filters.office} onChange={(event) => set('office', event.target.value)}><option value="">Todas</option>{facets.offices.map((item) => <option value={item.value} disabled={!item.count} key={item.value}>{officeLabel(item.value as Legislator['office'])} ({item.count})</option>)}</select></Field><Field label="Distrito"><select value={filters.district} onChange={(event) => set('district', event.target.value)}><option value="">Todos</option>{facets.districts.map((item) => <option value={item.value} disabled={!item.count} key={item.value}>{item.value} ({item.count})</option>)}</select></Field><Field label="Partido"><select value={filters.party} onChange={(event) => set('party', event.target.value)}><option value="">Todos</option>{facets.parties.map((item) => <option value={item.value} disabled={!item.count} key={item.value}>{item.value} ({item.count})</option>)}</select></Field><Field label="Bloque"><select value={filters.bloc} onChange={(event) => set('bloc', event.target.value)}><option value="">Todos</option>{facets.blocs.map((item) => <option value={item.value} disabled={!item.count} key={item.value}>{item.value} ({item.count})</option>)}</select></Field></div>;
}

function SourcesEditor({ items, onChange }: { items: Source[]; onChange: (items: Source[]) => void }) {
  const add = () => onChange([...items, { id: crypto.randomUUID(), label: '', url: '', publishedAt: null }]);
  return <section className="nested-editor"><div className="panel-title"><h3>Fuentes</h3><button className="button ghost" type="button" onClick={add}>Agregar fuente</button></div>{items.map((item, index) => <div className="nested-row" key={item.id}><Field label="Nombre"><input value={item.label} onChange={(e) => onChange(replaceAt(items, index, { ...item, label: e.target.value }))} /></Field><Field label="URL"><input type="url" value={item.url} onChange={(e) => onChange(replaceAt(items, index, { ...item, url: e.target.value }))} /></Field><button className="button danger" type="button" onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}>Quitar</button></div>)}</section>;
}

function DocumentsEditor({ items, onChange, project, call, notify }: { items: OfficialDocument[]; onChange: (items: OfficialDocument[]) => void; project?: Project; call: AdminProps['call']; notify: (value: string) => void }) {
  const add = () => onChange([...items, { id: crypto.randomUUID(), title: '', kind: 'link', url: '', sourceLabel: '', documentDate: null }]);
  async function upload(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const payload = new FormData(form); try { const body = await call('/v1/manage/documents', { method: 'POST', body: payload }); onChange([...items, { id: body.item.id, title: body.item.title, kind: 'pdf', url: body.item.url, sourceLabel: body.item.sourceLabel, documentDate: body.item.documentDate }]); form.reset(); notify('PDF cargado y agregado al borrador. Guardá el proyecto para conservar la relación.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos cargar el PDF.'); } }
  return <section className="nested-editor"><div className="panel-title"><h3>Documentos oficiales</h3><button className="button ghost" type="button" onClick={add}>Agregar enlace</button></div>{items.map((item, index) => <div className="nested-row" key={item.id}><Field label="Título"><input value={item.title} onChange={(e) => onChange(replaceAt(items, index, { ...item, title: e.target.value }))} /></Field><Field label="URL"><input type="url" value={item.url} onChange={(e) => onChange(replaceAt(items, index, { ...item, url: e.target.value }))} /></Field><Field label="Fuente"><input value={item.sourceLabel} onChange={(e) => onChange(replaceAt(items, index, { ...item, sourceLabel: e.target.value }))} /></Field><Field label="Fecha"><input type="date" value={item.documentDate || ''} onChange={(e) => onChange(replaceAt(items, index, { ...item, documentDate: e.target.value || null }))} /></Field><button className="button danger" type="button" onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}>Quitar</button></div>)}{project && <form className="pdf-upload" onSubmit={upload}><strong>Cargar PDF privado</strong><input name="title" placeholder="Título" required /><input name="sourceLabel" placeholder="Fuente" required /><input name="documentDate" type="date" required /><input name="file" type="file" accept="application/pdf" required /><button className="button ghost">Subir PDF</button></form>}</section>;
}

function UpdatesEditor({ items, publishedItems, onChange, workflow, canSave, saving, onSave }: { items: ProjectUpdate[]; publishedItems: ProjectUpdate[]; onChange: (items: ProjectUpdate[]) => void; workflow: WorkflowDefinition; canSave: boolean; saving: boolean; onSave: () => Promise<void> }) {
  const [editingPublished, setEditingPublished] = useState<Set<string>>(() => new Set());
  const [pendingAction, setPendingAction] = useState<{ type: 'edit' | 'remove'; id: string } | null>(null);
  const publishedById = useMemo(() => new Map(publishedItems.map((item) => [item.id, item])), [publishedItems]);
  const add = () => onChange([...items, { id: crypto.randomUUID(), date: new Date().toISOString().slice(0, 10), title: '', body: '', stageId: null, showStageChange: true, sources: [] }]);
  function confirmAction() {
    if (!pendingAction) return;
    if (pendingAction.type === 'edit') setEditingPublished((current) => new Set([...current, pendingAction.id]));
    else {
      onChange(items.filter((item) => item.id !== pendingAction.id));
      setEditingPublished((current) => { const next = new Set(current); next.delete(pendingAction.id); return next; });
    }
    setPendingAction(null);
  }
  const actionItem = pendingAction ? items.find((item) => item.id === pendingAction.id) : null;
  const actionWasPublished = Boolean(actionItem && publishedById.has(actionItem.id));
  return <section className="nested-editor chronology-editor">
    <div className="panel-title"><div><h3>Cronología pública</h3><p>Las entradas publicadas quedan protegidas. La última actualización fechada que indique una etapa define el estado visible del proyecto.</p></div><div className="nested-actions"><button className="button ghost" type="button" onClick={add}>Agregar actualización</button><button className="button primary" type="button" onClick={() => void onSave()} disabled={!canSave || saving} title={!canSave ? 'No hay cambios de cronología para guardar' : undefined}>{saving ? 'Guardando…' : 'Guardar cronología'}</button></div></div>
    <div className="chronology-list">{items.map((item, index) => {
      const publishedItem = publishedById.get(item.id);
      const hasPendingChange = Boolean(publishedItem && !sameValue(item, publishedItem));
      const locked = Boolean(publishedItem && !hasPendingChange && !editingPublished.has(item.id));
      const stateLabel = !publishedItem ? 'Nueva' : hasPendingChange ? 'Edición pendiente' : locked ? 'Publicada' : 'Edición habilitada';
      return <article className={`chronology-card ${publishedItem ? 'was-published' : 'is-new'} ${locked ? 'is-locked' : ''} ${hasPendingChange ? 'has-pending-change' : ''}`} key={item.id}>
        <div className="chronology-card-head"><div><span className="chronology-state">{stateLabel}</span><strong>{item.title || 'Actualización sin título'}</strong></div><div className="chronology-card-actions">{locked && <button className="button ghost compact" type="button" onClick={() => setPendingAction({ type: 'edit', id: item.id })}>Editar</button>}<button className="button danger compact" type="button" onClick={() => setPendingAction({ type: 'remove', id: item.id })}>Quitar</button></div></div>
        <div className="chronology-main-fields"><Field label="Fecha"><input type="date" value={item.date} disabled={locked} onChange={(e) => onChange(replaceAt(items, index, { ...item, date: e.target.value }))} /></Field><Field label="Título"><input value={item.title} disabled={locked} onChange={(e) => onChange(replaceAt(items, index, { ...item, title: e.target.value }))} /></Field><Field label="Etapa"><select value={item.stageId || ''} disabled={locked} onChange={(e) => onChange(replaceAt(items, index, { ...item, stageId: e.target.value || null, showStageChange: e.target.value ? item.showStageChange !== false : true }))}><option value="">Sin cambio de etapa</option>{workflow.stages.map((stage) => <option value={stage.id} key={stage.id}>{stage.label}</option>)}</select></Field></div>
        {item.stageId && <label className="chronology-stage-visibility"><input type="checkbox" checked={item.showStageChange !== false} disabled={locked} onChange={(event) => onChange(replaceAt(items, index, { ...item, showStageChange: event.target.checked }))} /><span><strong>Mostrar el cambio de etapa</strong><small>La cronología pública señalará visualmente el paso desde la etapa anterior.</small></span></label>}
        <div className="chronology-explanation"><Field label="Explicación pública"><textarea value={item.body} disabled={locked} onChange={(e) => onChange(replaceAt(items, index, { ...item, body: e.target.value }))} /></Field></div>
      </article>;
    })}</div>
    {!items.length && <div className="empty-state"><strong>Todavía no hay entradas.</strong><span>Agregá la primera actualización cuando exista un avance público para comunicar.</span></div>}
    {pendingAction && actionItem && <div className="dialog-backdrop" onMouseDown={() => setPendingAction(null)}><section className="dialog warning-dialog" role="alertdialog" aria-labelledby="chronology-action-title" aria-describedby="chronology-action-description" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Confirmación requerida</span><h2 id="chronology-action-title">{pendingAction.type === 'edit' ? '¿Editar esta actualización?' : '¿Quitar esta actualización?'}</h2><div className="confirmation-card"><strong>{actionItem.title || 'Actualización sin título'}</strong><p id="chronology-action-description">{pendingAction.type === 'edit' ? 'Vas a habilitar la edición de una entrada que ya está publicada. La versión pública no cambiará hasta que guardes la cronología y publiques una nueva revisión global.' : actionWasPublished ? 'Esta entrada ya forma parte de la cronología pública. Se quitará del borrador, pero seguirá visible hasta que publiques una nueva revisión global.' : 'Esta entrada todavía no está publicada. Si la quitás, se eliminarán los datos que cargaste en ella.'}</p></div><div className="dialog-actions"><button className="button ghost" type="button" onClick={() => setPendingAction(null)}>Cancelar</button><button className={pendingAction.type === 'remove' ? 'button danger' : 'button primary'} type="button" onClick={confirmAction}>{pendingAction.type === 'edit' ? 'Sí, habilitar edición' : 'Sí, quitar'}</button></div></section></div>}
  </section>;
}

function ProjectGlossarySettings({ terms, form, enabled, excludedIds, occurrenceMode, excludedOccurrenceIds, onEnabledChange, onExcludedChange, onOccurrenceModeChange, onExcludedOccurrenceChange }: {
  terms: GlossaryTerm[]; form: ProjectInput; enabled: boolean; excludedIds: string[]; occurrenceMode: 'all' | 'first' | 'custom'; excludedOccurrenceIds: string[];
  onEnabledChange: (value: boolean) => void; onExcludedChange: (value: string[]) => void; onOccurrenceModeChange: (value: 'all' | 'first' | 'custom') => void; onExcludedOccurrenceChange: (value: string[]) => void;
}) {
  const [query, setQuery] = useState('');
  const excluded = useMemo(() => new Set(excludedIds), [excludedIds]);
  const excludedOccurrences = useMemo(() => new Set(excludedOccurrenceIds), [excludedOccurrenceIds]);
  const sections = useMemo(() => [
    { id: 'summary', label: 'Resumen', text: richTextPlainText(form.summary || '', form.summaryFormat || 'plain') },
    { id: 'impact', label: '¿Cómo me afecta?', text: richTextPlainText(form.impact || '', form.impactFormat || 'plain') },
    ...(form.updates || []).map((update, index) => ({ update, index })).sort((a, b) => b.update.date.localeCompare(a.update.date) || b.index - a.index).map(({ update }) => ({ id: `update-${update.id}`, label: `Cronología · ${update.title || update.date}`, text: update.body })),
  ], [form.impact, form.impactFormat, form.summary, form.summaryFormat, form.updates]);
  const texts = useMemo(() => sections.map((section) => section.text), [sections]);
  const candidates = useMemo(() => terms
    .filter((term) => term.published && term.inlineEnabled)
    .filter((term) => !query.trim() || searchKey(`${term.term} ${term.aliases.join(' ')}`).includes(searchKey(query)))
    .sort((a, b) => a.term.localeCompare(b.term, 'es')), [excluded, query, terms, texts]);
  const toggleExcluded = (id: string, checked: boolean) => onExcludedChange(checked ? [...new Set([...excludedIds, id])] : excludedIds.filter((item) => item !== id));
  const occurrences = useMemo(() => sections.flatMap((section) => {
    const ordinals = new Map<string, number>();
    const eligible = terms.filter((term) => term.published && term.inlineEnabled && !excluded.has(term.id));
    return glossaryMatches(section.text, eligible, 'all').map((match) => {
      const ordinal = ordinals.get(match.term.id) || 0; ordinals.set(match.term.id, ordinal + 1);
      const contextStart = Math.max(0, match.start - 46); const contextEnd = Math.min(section.text.length, match.start + match.text.length + 46);
      return { id: glossaryOccurrenceId(section.id, match.term.id, ordinal), section: section.label, term: match.term.term, text: match.text, context: `${contextStart ? '…' : ''}${section.text.slice(contextStart, contextEnd).trim()}${contextEnd < section.text.length ? '…' : ''}` };
    });
  }), [excluded, sections, terms]);
  const toggleOccurrence = (id: string, checked: boolean) => onExcludedOccurrenceChange(checked ? excludedOccurrenceIds.filter((item) => item !== id) : [...new Set([...excludedOccurrenceIds, id])]);
  return <details className="project-glossary-settings">
    <summary><span><strong>Opciones avanzadas del glosario</strong><small>{enabled ? `${excludedIds.length} término(s) excluido(s) · ${occurrenceMode === 'all' ? 'todas las apariciones' : occurrenceMode === 'first' ? 'sólo la primera aparición' : 'control fino por aparición'}` : 'Desactivado para este proyecto'}</small></span><span aria-hidden="true">⌄</span></summary>
    <div className="project-glossary-settings-body">
      <label className="check-row"><input type="checkbox" checked={enabled} onChange={(event) => onEnabledChange(event.target.checked)} /><span>Mostrar glosario contextual en este proyecto</span></label>
      <Field label="Glosario repetido"><select value={occurrenceMode} disabled={!enabled} onChange={(event) => onOccurrenceModeChange(event.target.value as 'all' | 'first' | 'custom')}><option value="all">Marcar todas las apariciones</option><option value="first">Marcar sólo la primera aparición del proyecto</option><option value="custom">Elegir cada aparición manualmente</option></select></Field>
      <div className="glossary-blacklist-heading"><div><strong>Lista negra del proyecto</strong><span>Los términos seleccionados no se remarcan ni aparecen en las tarjetas del glosario.</span></div><input type="search" value={query} disabled={!enabled} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar término o alias" aria-label="Buscar términos para excluir" /></div>
      <div className="glossary-blacklist">{candidates.map((term) => <label className="check-row" key={term.id}><input type="checkbox" checked={excluded.has(term.id)} disabled={!enabled} onChange={(event) => toggleExcluded(term.id, event.target.checked)} /><span><strong>{term.term}</strong><small>{glossaryTermAppearsInTexts(term, texts) ? 'Detectado en el proyecto' : excluded.has(term.id) ? 'Exclusión guardada' : 'No detectado actualmente'}</small></span></label>)}{!candidates.length && <p>No hay términos activos coincidentes con esta búsqueda.</p>}</div>
      {occurrenceMode === 'custom' && <section className="glossary-occurrence-control"><div><strong>Control fino por aparición</strong><span>Activá únicamente las coincidencias que querés convertir en acceso al glosario.</span></div><div className="glossary-occurrence-list">{occurrences.map((occurrence) => <label key={occurrence.id}><input type="checkbox" checked={!excludedOccurrences.has(occurrence.id)} disabled={!enabled} onChange={(event) => toggleOccurrence(occurrence.id, event.target.checked)} /><span><strong>{occurrence.term}</strong><small>{occurrence.section}</small><em>{occurrence.context}</em></span></label>)}{!occurrences.length && <p>No hay apariciones disponibles con la configuración actual.</p>}</div></section>}
    </div>
  </details>;
}

function replaceAt<T>(items: T[], index: number, value: T) { return items.map((item, itemIndex) => itemIndex === index ? value : item); }

function PreviewDialog({ project, form, settings, call, close }: { project: Project; form: ProjectInput; settings: SiteSettings; call: AdminProps['call']; close: () => void }) {
  const [item, setItem] = useState<PublicProject | null>(null); const [error, setError] = useState(''); const closeButton = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    call(`/v1/manage/projects/${project.id}/preview`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) }).then((body) => setItem(body.item as PublicProject)).catch((caught) => setError(caught instanceof Error ? caught.message : 'No pudimos preparar la vista previa.'));
  }, [call, form, project.id]);
  useEffect(() => { closeButton.current?.focus(); const onKeyDown = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); }; window.addEventListener('keydown', onKeyDown); return () => window.removeEventListener('keydown', onKeyDown); }, [close]);
  return <div className="private-preview" role="dialog" aria-modal="true" aria-labelledby="private-preview-title">
    <div className="private-preview-toolbar"><div><span className="eyebrow">Vista previa privada</span><strong id="private-preview-title">Así se verá la ficha pública</strong><span>Incluye los cambios actuales de la pantalla. No guarda ni publica contenido.</span></div><button ref={closeButton} className="button dark" type="button" onClick={close}>Cerrar vista previa</button></div>
    <div className="private-preview-document">{error ? <section className="preview-error"><h2>No pudimos mostrar la vista previa</h2><p className="message error" role="alert">{error}</p><button className="button primary" type="button" onClick={close}>Volver al editor</button></section> : item ? <><SiteHeader /><ProjectDetail project={item} subscriptionsEnabled={settings.subscriptionsEnabled} stageExplanations={settings.legislativeStageExplanations} contentId="contenido-vista-previa" /><SiteFooter /></> : <div className="preview-loading" role="status"><span className="eyebrow">Preparando ficha</span><strong>Cargando la visualización exacta…</strong></div>}</div>
  </div>;
}

function PublishDialog({ project, canNotifyFollowers, suggestedNotify, call, reload, notify, close }: { project: Project; canNotifyFollowers: boolean; suggestedNotify: boolean; call: AdminProps['call']; reload: () => Promise<void>; notify: (value: string) => void; close: () => void }) {
  const [summary, setSummary] = useState(''); const [send, setSend] = useState(canNotifyFollowers && suggestedNotify); const [confirming, setConfirming] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit() { setBusy(true); setError(''); try { await call(`/v1/manage/projects/${project.id}/publish`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ changeSummary: summary, notifyFollowers: canNotifyFollowers && send }) }); await reload(); notify('La revisión fue publicada y la caché pública se está actualizando.'); close(); } catch (caught) { setError(caught instanceof Error ? caught.message : 'No pudimos publicar.'); } finally { setBusy(false); } }
  return <div className="dialog-backdrop" onMouseDown={() => !busy && close()}><section className="dialog" role="dialog" aria-modal="true" aria-labelledby="publish-title" onMouseDown={(e) => e.stopPropagation()}><span className="eyebrow">Nueva revisión inmutable</span><h2 id="publish-title">Publicar {project.title}</h2>{!confirming ? <><Field label="Resumen del cambio (opcional)"><textarea value={summary} maxLength={500} onChange={(e) => setSummary(e.target.value)} placeholder="Qué cambió y por qué" /></Field><p className="field-help">Podés dejarlo vacío. El historial registrará igualmente quién publicó, cuándo y qué versión quedó visible.</p>{canNotifyFollowers && <label className="check-row"><input type="checkbox" checked={send} onChange={(e) => setSend(e.target.checked)} /><span>Notificar a seguidores{suggestedNotify ? ' (sugerido porque cambió la etapa)' : ' (opcional para esta actualización de la cronología)'}</span></label>}<div className="dialog-actions"><button className="button ghost" onClick={close}>Cancelar</button><button className="button primary" onClick={() => setConfirming(true)}>Revisar publicación</button></div></> : <><div className="confirmation-card"><strong>Confirmá antes de hacer público el cambio</strong><dl><dt>Proyecto</dt><dd>{project.title}</dd><dt>Resumen</dt><dd>{summary.trim() || 'Sin resumen editorial'}</dd>{canNotifyFollowers && <><dt>Seguidores</dt><dd>{send ? 'Se enviará una notificación' : 'No se enviarán notificaciones'}</dd></>}</dl><p>Se creará una revisión inmutable y la ficha pública pasará a mostrar esta versión.</p></div>{error && <p className="message error" role="alert">{error}</p>}<div className="dialog-actions"><button className="button ghost" disabled={busy} onClick={() => setConfirming(false)}>Volver</button><button className="button primary" disabled={busy} onClick={() => void submit()}>{busy ? 'Publicando…' : 'Sí, publicar revisión'}</button></div></>}</section></div>;
}

function Legislators({ data, call, reload, notify, admin }: AdminProps & { admin: boolean }) {
  type LegislatorForm = { fullName: string; slug: string; party: string; bloc: string; district: string; office: Legislator['office']; mandateStart: string; mandateEnd: string; academicTitle: string; bio: string; attendanceValue: string; attendanceAsOf: string; attendanceSourceUrl: string; published: boolean };
  type ProfileFeedback = { kind: 'status' | 'error'; text: string };
  const emptyForm = (): LegislatorForm => ({ fullName: '', slug: '', party: '', bloc: '', district: '', office: 'diputado', mandateStart: '', mandateEnd: '', academicTitle: '', bio: '', attendanceValue: '', attendanceAsOf: '', attendanceSourceUrl: '', published: false });
  const [form, setForm] = useState<LegislatorForm>(() => emptyForm()); const [baseline, setBaseline] = useState(JSON.stringify(emptyForm())); const [selectedId, setSelectedId] = useState(''); const [profileSaving, setProfileSaving] = useState(false);
  const [profileFeedback, setProfileFeedback] = useState<ProfileFeedback | null>(null);
  const [integration, setIntegration] = useState<IntegrationOverview | null>(null); const [query, setQuery] = useState(''); const [results, setResults] = useState<ExternalLegislatorSearchItem[]>([]); const [sourceBusy, setSourceBusy] = useState(false);
  const [changes, setChanges] = useState<LegislatorImportSuggestion[]>([]); const [changeStatus, setChangeStatus] = useState('pending');
  const [bulkConfirm, setBulkConfirm] = useState(false); const [bulkBusy, setBulkBusy] = useState(false); const [bulkError, setBulkError] = useState('');
  const lastAutomaticRefresh = useRef(0); const automaticRefreshInFlight = useRef<Promise<unknown> | null>(null);
  const selectedProfile = data.legislators.find((item) => item.id === selectedId) || null;
  const profileDirty = JSON.stringify(form) !== baseline;
  const attendanceValues = [form.attendanceValue.trim(), form.attendanceAsOf.trim(), form.attendanceSourceUrl.trim()];
  const attendanceIncomplete = attendanceValues.some(Boolean) && !attendanceValues.every(Boolean);
  const attendanceNumber = Number(form.attendanceValue);
  const attendanceInvalid = Boolean(form.attendanceValue.trim()) && (!Number.isFinite(attendanceNumber) || attendanceNumber < 0 || attendanceNumber > 100);
  const attendanceSourceInvalid = Boolean(form.attendanceSourceUrl.trim()) && !isHttpUrl(form.attendanceSourceUrl);
  const profileBlockingMessage = !profileDirty ? 'Modificá al menos un dato para habilitar el guardado.'
    : form.fullName.trim().length < 3 ? 'El nombre completo debe tener al menos tres caracteres.'
      : !form.slug ? 'Completá un slug válido para guardar el perfil.'
        : attendanceIncomplete ? 'La asistencia es un dato trazable: completá porcentaje, fecha de corte y fuente, o dejá los tres campos vacíos.'
          : attendanceInvalid ? 'La asistencia debe ser un porcentaje entre 0 y 100.'
            : attendanceSourceInvalid ? 'La fuente de asistencia debe ser una URL válida que comience con http:// o https://.' : '';
  const sources = integration?.sources || [];
  const enabledSources = sources.filter((item) => item.enabled);
  const importReady = enabledSources.length === 2 && enabledSources.every((item) => item.lastSnapshotId && item.mode !== 'shadow');
  const loadIntegration = useCallback(async () => { try { setIntegration(await call('/v1/manage/integrations')); } catch { setIntegration(null); } }, [call]);
  const loadChanges = useCallback(async () => { try { const body = await call(`/v1/manage/integrations/legislators/changes?status=${encodeURIComponent(changeStatus)}&pageSize=100`); setChanges(body.items || []); } catch { setChanges([]); } }, [call, changeStatus]);
  const automaticRefresh = useCallback(() => {
    if (document.visibilityState !== 'visible' || Date.now() - lastAutomaticRefresh.current < 15_000 || automaticRefreshInFlight.current) return;
    lastAutomaticRefresh.current = Date.now();
    const request = Promise.all([loadIntegration(), loadChanges()]).finally(() => { if (automaticRefreshInFlight.current === request) automaticRefreshInFlight.current = null; });
    automaticRefreshInFlight.current = request;
  }, [loadChanges, loadIntegration]);
  useEffect(() => { automaticRefresh(); }, [automaticRefresh]);
  useEffect(() => { const timer = window.setInterval(automaticRefresh, 60_000); window.addEventListener('focus', automaticRefresh); document.addEventListener('visibilitychange', automaticRefresh); return () => { window.clearInterval(timer); window.removeEventListener('focus', automaticRefresh); document.removeEventListener('visibilitychange', automaticRefresh); }; }, [automaticRefresh]);
  function formFor(item: Legislator): LegislatorForm { return { fullName: item.fullName, slug: item.slug, party: item.party || '', bloc: item.bloc || '', district: item.district || '', office: item.office, mandateStart: item.mandateStart || '', mandateEnd: item.mandateEnd || '', academicTitle: item.academicTitle || '', bio: item.bio || '', attendanceValue: item.attendance ? String(item.attendance.value) : '', attendanceAsOf: item.attendance?.asOf || '', attendanceSourceUrl: item.attendance?.sourceUrl || '', published: item.published }; }
  function editProfile(item: Legislator, discardCurrent = false) { if (!discardCurrent && profileDirty && !window.confirm('Hay cambios sin guardar en el perfil actual. ¿Querés descartarlos y editar otro perfil?')) return; const next = formFor(item); setSelectedId(item.id); setForm(next); setBaseline(JSON.stringify(next)); setProfileFeedback(null); }
  function newProfile() { if (profileDirty && !window.confirm('Hay cambios sin guardar. ¿Querés descartarlos y crear un perfil nuevo?')) return; const next = emptyForm(); setSelectedId(''); setForm(next); setBaseline(JSON.stringify(next)); setProfileFeedback(null); }
  async function save() {
    if (profileSaving) return;
    if (profileBlockingMessage) { setProfileFeedback({ kind: 'error', text: profileBlockingMessage }); return; }
    setProfileSaving(true);
    setProfileFeedback({ kind: 'status', text: 'Guardando el perfil en la base persistente…' });
    try {
      const attendance = attendanceValues.every(Boolean) ? { value: Number(form.attendanceValue), asOf: form.attendanceAsOf, sourceUrl: form.attendanceSourceUrl } : null;
      const payload = { fullName: form.fullName, slug: form.slug, party: form.party, bloc: form.bloc, district: form.district, office: form.office, mandateStart: form.mandateStart || null, mandateEnd: form.mandateEnd || null, academicTitle: form.academicTitle, bio: form.bio, attendance, published: form.published };
      const body = await call(selectedId ? `/v1/manage/legislators/${selectedId}` : '/v1/manage/legislators', { method: selectedId ? 'PUT' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
      const created = !selectedId; const next = formFor(body.item); setSelectedId(body.item.id); setForm(next); setBaseline(JSON.stringify(next)); setProfileFeedback({ kind: 'status', text: created ? 'Perfil creado y guardado correctamente.' : 'Cambios guardados correctamente.' }); notify(created ? 'Perfil creado.' : 'Perfil actualizado.');
      try { await reload(); } catch { setProfileFeedback({ kind: 'status', text: 'Los cambios se guardaron, pero no pudimos refrescar la lista. Recargá la página para verla actualizada.' }); }
    } catch (error) { const text = error instanceof Error ? error.message : 'No pudimos guardar.'; setProfileFeedback({ kind: 'error', text }); notify(text); }
    finally { setProfileSaving(false); }
  }
  async function syncSource(source: ExternalSource, forceDownload = false) { setSourceBusy(true); try { const body = await call(`/v1/manage/integrations/${source.id}/sync`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ forceDownload }) }); notify(body.unchanged ? `${source.label}: la fuente no presenta cambios.` : `${source.label}: ${body.imported} registros validados; ${body.changes?.added || 0} altas, ${body.changes?.changed || 0} cambios y ${body.changes?.removed || 0} bajas para revisar.`); setResults([]); await Promise.all([loadIntegration(), loadChanges()]); } catch (error) { notify(error instanceof Error ? error.message : `No pudimos sincronizar ${source.label}.`); } finally { setSourceBusy(false); } }
  async function syncAll(forceDownload = false) { setSourceBusy(true); try { const body = await call('/v1/manage/integrations/legislators/sync-all', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ forceDownload }) }); const failed = body.results.filter((item: { ok: boolean }) => !item.ok).length; notify(failed ? `La comprobación terminó con ${failed} fuente(s) que requieren atención.` : 'Diputados y Senado quedaron comprobados.'); setResults([]); await Promise.all([loadIntegration(), loadChanges()]); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos comprobar ambas fuentes.'); } finally { setSourceBusy(false); } }
  async function bulkImport() { if (!importReady) return; setBulkBusy(true); setBulkError(''); try { const body = await call('/v1/manage/integrations/legislators/bulk-import-all', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ snapshots: enabledSources.map((source) => ({ sourceId: source.id, snapshotId: source.lastSnapshotId })) }) }); const totals = body.totals; await Promise.all([reload(), loadIntegration()]); setBulkConfirm(false); notify(`Importación bicameral terminada: ${totals.created} perfiles privados creados, ${totals.alreadyLinked + totals.resumed} ya vinculados o recuperados${totals.needsReview ? ` y ${totals.needsReview} separados para revisión` : ''}${totals.failed ? `. Fallaron ${totals.failed}` : ''}.`); } catch (error) { setBulkError(error instanceof Error ? error.message : 'No pudimos completar la importación masiva.'); } finally { setBulkBusy(false); } }
  async function search(event?: React.FormEvent) { event?.preventDefault(); setSourceBusy(true); try { const body = await call(`/v1/manage/integrations/legislators/search?q=${encodeURIComponent(query)}`); setResults(body.items); if (!body.items.length) notify('No encontramos coincidencias en los últimos snapshots válidos.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos buscar legisladores.'); } finally { setSourceBusy(false); } }
  return <>
    <section className="admin-panel source-panel"><div className="panel-title"><div><span className="eyebrow">Fuentes oficiales asistidas</span><h2>Congreso de la Nación</h2><p>La búsqueda usa el último caché privado válido. Los cambios oficiales esperan revisión humana.</p></div>{admin && <div className="source-heading-actions"><button className="button ghost" onClick={() => void syncAll()} disabled={!enabledSources.length || sourceBusy || bulkBusy}>{sourceBusy ? 'Comprobando…' : 'Comprobar ambas fuentes'}</button><button className="button primary" onClick={() => { setBulkError(''); setBulkConfirm(true); }} disabled={!importReady || sourceBusy || bulkBusy}>Importar todos los legisladores</button></div>}</div>
      {sources.map((source) => <div className="source-card" key={source.id}><div className="source-meta"><span>{source.label}<strong>{source.enabled ? freshnessLabel(source.freshness) : 'Desactivada'}</strong></span><span>Última comprobación<strong>{source.lastSuccessfulSyncAt ? formatDateTime(source.lastSuccessfulSyncAt) : 'Todavía no sincronizado'}</strong></span><span>Próxima revisión<strong>{source.nextScheduledSyncAt ? formatDateTime(source.nextScheduledSyncAt) : 'Pendiente'}</strong></span><span>Cambios pendientes<strong>{source.pendingChanges}</strong></span></div>{source.lastError && <p className="message error">{source.lastError}</p>}{admin && <div className="source-card-actions"><button className="button ghost" onClick={() => void syncSource(source)} disabled={!source.enabled || sourceBusy || bulkBusy}>{sourceBusy ? 'Esperá…' : `Comprobar ${source.id === 'senate-legislators' ? 'Senado' : 'Diputados'} ahora`}</button><details><summary>Acciones avanzadas</summary><button className="button danger" onClick={() => { if (window.confirm(`¿Forzar una descarga completa de ${source.label}?`)) void syncSource(source, true); }} disabled={sourceBusy}>Forzar descarga completa</button></details></div>}</div>)}
      {!enabledSources.length ? <div className="source-disabled"><strong>Integraciones apagadas por configuración.</strong><p>Activá <code>CONGRESS_IMPORT_ENABLED</code>, <code>HCDN_IMPORT_ENABLED</code> y <code>SENATE_IMPORT_ENABLED</code> en la API. La web pública no se modifica.</p></div> : <><div className="source-meta"><span>Registros oficiales privados<strong>{integration?.counts.legislators || 0}</strong></span><span>Perfiles vinculados<strong>{integration?.counts.links || 0}</strong></span></div><form className="source-search" onSubmit={search}><Field label="Buscar por nombre, distrito, bloque o ID oficial"><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ej.: Buenos Aires, Pérez o HCDN1234" /></Field><button className="button primary" disabled={query.trim().length < 2 || sourceBusy}>Buscar en ambas cámaras</button></form></>}
      {enabledSources.some((source) => source.mode === 'shadow') && <p className="source-disabled">Al menos una fuente está en observación. Podés sincronizar y revisar resultados, pero la carga masiva requiere modo asistido.</p>}
      {results.length > 0 && <div className="external-results">{results.map((item) => { const itemSource = sources.find((source) => source.id === item.record.sourceId); return <ExternalLegislatorResult item={item} locals={data.legislators} call={call} reload={reload} notify={notify} refresh={() => search()} canImport={itemSource?.mode === 'assisted' || itemSource?.mode === 'active'} key={item.record.id} />; })}</div>}
    </section>
    <LegislatorChanges items={changes} status={changeStatus} setStatus={setChangeStatus} legislators={data.legislators} call={call} reload={async () => { await Promise.all([reload(), loadChanges(), loadIntegration()]); }} notify={notify} admin={admin} />
    {bulkConfirm && importReady && <div className="dialog-backdrop" onMouseDown={() => !bulkBusy && setBulkConfirm(false)}><section className="dialog" role="alertdialog" aria-labelledby="bulk-import-title" aria-describedby="bulk-import-description" onMouseDown={(event) => event.stopPropagation()}><span className="eyebrow">Carga inicial controlada</span><h2 id="bulk-import-title">Importar todo el Congreso</h2><div className="confirmation-card"><strong>Esta operación es privada e idempotente</strong><p id="bulk-import-description">Se crearán los perfiles faltantes de Diputados y Senado. Ningún perfil se publicará automáticamente y los existentes no serán sobrescritos.</p><dl>{enabledSources.map((source) => <Fragment key={source.id}><dt>{source.label}</dt><dd>{source.lastSnapshotId}</dd></Fragment>)}<dt>Destino</dt><dd>Perfiles privados de Quórum</dd></dl><p>Las coincidencias dudosas se separarán para revisión manual. Podés repetir la operación sin crear duplicados.</p></div>{bulkError && <p className="message error" role="alert">{bulkError}</p>}<div className="dialog-actions"><button className="button ghost" disabled={bulkBusy} onClick={() => setBulkConfirm(false)}>Cancelar</button><button className="button primary" disabled={bulkBusy} onClick={() => void bulkImport()}>{bulkBusy ? 'Importando…' : 'Sí, importar y guardar'}</button></div></section></div>}
    <div className="admin-two">
      <LegislatorProfiles items={data.legislators} selectedId={selectedId} onEdit={editProfile} />
      <section className="admin-panel legislator-profile-editor" onChangeCapture={() => setProfileFeedback(null)}>
        <div className="panel-title"><div><h2>{selectedProfile ? `Editar ${selectedProfile.fullName}` : 'Nuevo perfil manual'}</h2><p>{profileDirty ? 'Hay cambios sin guardar.' : selectedProfile ? 'El formulario coincide con el perfil guardado.' : 'Completá los datos para crear un perfil.'}</p></div>{selectedProfile && <button className="button ghost" type="button" onClick={newProfile}>Crear otro perfil</button>}</div>
        <Field label="Nombre completo"><input value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value, slug: selectedId ? form.slug : slugify(e.target.value) })} /></Field>
        <Field label="Slug estable"><input value={form.slug} disabled={Boolean(selectedProfile?.published)} onChange={(e) => setForm({ ...form, slug: slugify(e.target.value) })} /></Field>
        <div className="form-grid"><Field label="Cámara"><select value={form.office} onChange={(e) => setForm({ ...form, office: e.target.value as Legislator['office'] })}><option value="diputado">Diputado/a</option><option value="senador">Senador/a</option><option value="otro">Otro</option></select></Field><Field label="Distrito"><input value={form.district} onChange={(e) => setForm({ ...form, district: e.target.value })} /></Field><Field label="Partido"><input value={form.party} onChange={(e) => setForm({ ...form, party: e.target.value })} /></Field><Field label="Bloque"><input value={form.bloc} onChange={(e) => setForm({ ...form, bloc: e.target.value })} /></Field><Field label="Inicio del mandato"><input type="date" value={form.mandateStart} onChange={(e) => setForm({ ...form, mandateStart: e.target.value })} /></Field><Field label="Fin del mandato"><input type="date" value={form.mandateEnd} onChange={(e) => setForm({ ...form, mandateEnd: e.target.value })} /></Field></div>
        <Field label="Formación o título académico"><input value={form.academicTitle} onChange={(e) => setForm({ ...form, academicTitle: e.target.value })} /></Field>
        <Field label="Biografía"><textarea value={form.bio} onChange={(e) => setForm({ ...form, bio: e.target.value })} /></Field>
        <fieldset className="nested-editor legislator-attendance">
          <legend>Asistencia a sesiones (opcional)</legend>
          <p>Porcentaje de sesiones con asistencia registrada sobre el total computado por la fuente, a la fecha indicada. Cargalo sólo cuando la fuente explique o publique esta métrica. Para quitarlo, dejá los tres campos vacíos.</p>
          <div className="form-grid"><Field label="Asistencia registrada (%)"><input type="number" min="0" max="100" step="0.01" value={form.attendanceValue} onChange={(e) => setForm({ ...form, attendanceValue: e.target.value })} /></Field><Field label="Fecha de corte"><input type="date" value={form.attendanceAsOf} onChange={(e) => setForm({ ...form, attendanceAsOf: e.target.value })} /></Field></div>
          <Field label="Fuente de la asistencia"><input type="url" placeholder="https://…" value={form.attendanceSourceUrl} onChange={(e) => setForm({ ...form, attendanceSourceUrl: e.target.value })} /></Field>
          {(attendanceIncomplete || attendanceInvalid || attendanceSourceInvalid) && <p className="message error" role="alert">{attendanceIncomplete ? 'Completá porcentaje, fecha de corte y fuente, o dejá los tres campos vacíos.' : attendanceInvalid ? 'Ingresá un porcentaje entre 0 y 100.' : 'Ingresá una URL válida para la fuente.'}</p>}
        </fieldset>
        <label className="check-row"><input type="checkbox" checked={form.published} onChange={(e) => setForm({ ...form, published: e.target.checked })} /><span>Publicar perfil</span></label>
        {profileFeedback ? <p className={`message profile-save-feedback${profileFeedback.kind === 'error' ? ' error' : ''}`} id="profile-save-help" role={profileFeedback.kind === 'error' ? 'alert' : 'status'}>{profileFeedback.text}</p> : <p className="profile-save-help" id="profile-save-help">{profileBlockingMessage || 'Todo listo para guardar los cambios en Firestore.'}</p>}
        <div className="legislator-profile-editor-actions">{selectedProfile && <button className="button ghost" type="button" onClick={() => editProfile(selectedProfile, true)} disabled={!profileDirty}>Descartar cambios</button>}<button className="button primary" aria-describedby="profile-save-help" onClick={() => void save()} disabled={!profileDirty || profileSaving || Boolean(profileBlockingMessage)}>{profileSaving ? 'Guardando…' : selectedProfile ? 'Guardar cambios' : 'Crear perfil'}</button></div>
      </section>
    </div>
  </>;
}

function LegislatorProfiles({ items, selectedId, onEdit }: { items: Legislator[]; selectedId: string; onEdit: (item: Legislator) => void }) {
  const [query, setQuery] = useState(''); const [office, setOffice] = useState(''); const [district, setDistrict] = useState(''); const [visibility, setVisibility] = useState(''); const [page, setPage] = useState(1);
  const pageSize = 40;
  const districts = useMemo(() => [...new Set(items.map((item) => item.district).filter(Boolean))].sort((left, right) => left.localeCompare(right, 'es')), [items]);
  const filtered = useMemo(() => {
    const needle = searchKey(query);
    return [...items].filter((item) => {
      const matchesText = !needle || searchKey(`${item.fullName} ${item.bloc} ${item.party} ${item.district}`).includes(needle);
      return matchesText && (!office || item.office === office) && (!district || item.district === district) && (!visibility || (visibility === 'public' ? item.published : !item.published));
    }).sort((left, right) => left.fullName.localeCompare(right.fullName, 'es'));
  }, [district, items, office, query, visibility]);
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize)); const currentPage = Math.min(page, totalPages);
  const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize); const hasFilters = Boolean(query || office || district || visibility);
  function clear() { setQuery(''); setOffice(''); setDistrict(''); setVisibility(''); setPage(1); }
  return <section className="admin-panel profiles-panel"><div className="panel-title"><div><h2>Perfiles</h2><p>Buscá un perfil y elegí editar para completar, corregir o quitar información.</p></div></div><div className="profile-filters"><Field label="Buscar"><input type="search" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Nombre, bloque, partido o distrito" /></Field><Field label="Cámara"><select value={office} onChange={(event) => { setOffice(event.target.value); setPage(1); }}><option value="">Todas</option><option value="diputado">Diputados</option><option value="senador">Senado</option><option value="otro">Otros</option></select></Field><Field label="Distrito"><select value={district} onChange={(event) => { setDistrict(event.target.value); setPage(1); }}><option value="">Todos</option>{districts.map((item) => <option value={item} key={item}>{item}</option>)}</select></Field><Field label="Estado"><select value={visibility} onChange={(event) => { setVisibility(event.target.value); setPage(1); }}><option value="">Todos</option><option value="private">Privados</option><option value="public">Públicos</option></select></Field></div><div className="profile-results-head" aria-live="polite"><span><strong>{filtered.length}</strong> de {items.length} perfiles</span>{hasFilters && <button className="button ghost" type="button" onClick={clear}>Limpiar filtros</button>}</div>{visible.length ? <div className="table-list profile-edit-list">{visible.map((item) => <div className={selectedId === item.id ? 'selected' : ''} key={item.id}><span className="profile-edit-summary"><strong>{item.fullName}</strong><span>{officeLabel(item.office)} · {item.district || 'Sin distrito'} · {item.bloc || item.party || 'Sin bloque'} · {item.published ? 'Público' : 'Privado'}</span></span><button className="button ghost compact" type="button" onClick={() => onEdit(item)} aria-label={`Editar perfil de ${item.fullName}`}>{selectedId === item.id ? 'Editando' : 'Editar'}</button></div>)}</div> : <div className="empty-state"><strong>No hay perfiles para esos filtros.</strong><span>Probá otra búsqueda o limpiá la selección.</span></div>}{totalPages > 1 && <div className="profile-pagination" aria-label="Paginación de perfiles"><button className="button ghost" type="button" disabled={currentPage === 1} onClick={() => setPage((value) => Math.max(1, value - 1))}>Anterior</button><span>Página {currentPage} de {totalPages}</span><button className="button ghost" type="button" disabled={currentPage === totalPages} onClick={() => setPage((value) => Math.min(totalPages, value + 1))}>Siguiente</button></div>}</section>;
}

function LegislatorChanges({ items, status, setStatus, legislators, call, reload, notify, admin }: { items: LegislatorImportSuggestion[]; status: string; setStatus: (value: string) => void; legislators: Legislator[]; call: AdminProps['call']; reload: () => Promise<void>; notify: (value: string) => void; admin: boolean }) {
  const [source, setSource] = useState(''); const [kind, setKind] = useState(''); const [district, setDistrict] = useState(''); const [bloc, setBloc] = useState(''); const [linked, setLinked] = useState('');
  const districts = [...new Set(items.map((item) => item.district).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'es'));
  const blocs = [...new Set(items.map((item) => item.bloc).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'es'));
  const visible = items.filter((item) => (!source || item.sourceId === source) && (!kind || item.changeType === kind) && (!district || item.district === district) && (!bloc || item.bloc === bloc) && (!linked || (linked === 'yes' ? Boolean(item.localLegislatorId) : !item.localLegislatorId)));
  return <section className="admin-panel change-review-panel"><div className="panel-title"><div><span className="eyebrow">Revisión humana</span><h2>Cambios oficiales pendientes</h2><p>Compará la fuente anterior, la nueva y el valor actual en Quórum. Nada se aplica automáticamente.</p></div><span className="status-pill">{visible.length} resultado(s)</span></div><div className="profile-filters change-filters"><Field label="Estado"><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="pending">Pendientes</option><option value="dismissed">Descartados</option><option value="applied">Aplicados</option><option value="superseded">Reemplazados</option></select></Field><Field label="Cámara"><select value={source} onChange={(event) => setSource(event.target.value)}><option value="">Todas</option><option value="hcdn-legislators">Diputados</option><option value="senate-legislators">Senado</option></select></Field><Field label="Tipo"><select value={kind} onChange={(event) => setKind(event.target.value)}><option value="">Todos</option><option value="added">Altas</option><option value="changed">Cambios</option><option value="removed">Bajas</option></select></Field><Field label="Distrito"><select value={district} onChange={(event) => setDistrict(event.target.value)}><option value="">Todos</option>{districts.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Bloque"><select value={bloc} onChange={(event) => setBloc(event.target.value)}><option value="">Todos</option>{blocs.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Vinculación"><select value={linked} onChange={(event) => setLinked(event.target.value)}><option value="">Todas</option><option value="yes">Con perfil</option><option value="no">Sin perfil</option></select></Field></div>{visible.length ? <div className="change-review-list">{visible.map((item) => <LegislatorChangeCard item={item} local={legislators.find((candidate) => candidate.id === item.localLegislatorId) || null} call={call} reload={reload} notify={notify} admin={admin} key={item.id} />)}</div> : <div className="empty-state"><strong>No hay cambios para esos filtros.</strong><span>El último caché oficial sigue disponible.</span></div>}</section>;
}

function LegislatorChangeCard({ item, local, call, reload, notify, admin }: { item: LegislatorImportSuggestion; local: Legislator | null; call: AdminProps['call']; reload: () => Promise<void>; notify: (value: string) => void; admin: boolean }) {
  const importable = item.changes.map((change) => change.field).filter((field): field is LegislatorImportField => ['fullName','district','party','bloc','mandateStart','mandateEnd'].includes(field));
  const [fields, setFields] = useState<LegislatorImportField[]>(importable); const [busy, setBusy] = useState(false);
  async function apply() { if (!fields.length) return; const publicProfile = local?.published === true; if (publicProfile && !admin) { notify('Sólo un administrador puede aplicar datos oficiales a un perfil público.'); return; } const selectedChanges = item.changes.filter((change) => fields.includes(change.field as LegislatorImportField)).map((change) => `${changeFieldLabel(change.field)}: ${displayChangeValue(change.localValue)} → ${displayChangeValue(change.nextValue)}`).join('\n'); if (publicProfile && !window.confirm(`Estos datos de ${local?.fullName} cambiarán inmediatamente en la web pública:\n\n${selectedChanges}\n\n¿Continuar?`)) return; setBusy(true); try { await call(`/v1/manage/integrations/legislators/changes/${encodeURIComponent(item.id)}/apply`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ fields, confirmPublic: publicProfile }) }); await reload(); notify('Cambio oficial aplicado y revisión inmutable creada.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos aplicar el cambio.'); } finally { setBusy(false); } }
  async function dismiss() { const reason = window.prompt(item.changeType === 'removed' ? 'Indicá cómo se revisó esta baja oficial. El perfil no se eliminará.' : 'Motivo para descartar este cambio'); if (!reason?.trim()) return; setBusy(true); try { await call(`/v1/manage/integrations/legislators/changes/${encodeURIComponent(item.id)}/dismiss`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ reason }) }); await reload(); notify('Cambio marcado como revisado.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos revisar el cambio.'); } finally { setBusy(false); } }
  async function reopen() { setBusy(true); try { await call(`/v1/manage/integrations/legislators/changes/${encodeURIComponent(item.id)}/reopen`, { method: 'POST' }); await reload(); notify('Cambio reabierto.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos reabrirlo.'); } finally { setBusy(false); } }
  return <article className="change-review-card"><header><div><span className={`change-kind ${item.changeType}`}>{changeTypeLabel(item.changeType)}</span><h3>{item.fullName}</h3><p>{item.sourceId === 'senate-legislators' ? 'Senado' : 'Diputados'} · {item.district || 'Sin distrito'} · {item.bloc || 'Sin bloque'}</p></div><div><span>{item.localLegislatorId ? `Vinculado a ${local?.fullName || item.localLegislatorId}` : 'Sin perfil vinculado'}</span>{item.officialUrl && <a href={item.officialUrl} target="_blank" rel="noreferrer">Ficha oficial ↗</a>}</div></header><div className="change-table"><div className="change-table-head"><span>Campo</span><span>Oficial anterior</span><span>Oficial nuevo</span><span>Quórum actual</span></div>{item.changes.map((change) => { const selectable = importable.includes(change.field as LegislatorImportField); return <label className="change-row" key={change.field}><span>{selectable && item.status === 'pending' && item.changeType !== 'removed' && <input type="checkbox" checked={fields.includes(change.field as LegislatorImportField)} onChange={(event) => setFields((current) => event.target.checked ? [...new Set([...current, change.field as LegislatorImportField])] : current.filter((field) => field !== change.field))} />}<strong>{changeFieldLabel(change.field)}</strong></span><span>{displayChangeValue(change.previousValue)}</span><span>{displayChangeValue(change.nextValue)}</span><span>{displayChangeValue(change.localValue)}</span></label>; })}</div><footer><span>Snapshot {item.nextSnapshotId} · {new Date(item.createdAt).toLocaleString('es-AR')}</span><div>{item.status === 'pending' && item.changeType !== 'removed' && <button className="button primary" disabled={busy || !fields.length} onClick={() => void apply()}>{busy ? 'Aplicando…' : item.changeType === 'added' ? 'Crear perfil privado' : 'Aplicar seleccionados'}</button>}{item.status === 'pending' && admin && <button className="button ghost" disabled={busy} onClick={() => void dismiss()}>{item.changeType === 'removed' ? 'Marcar baja revisada' : 'Descartar con motivo'}</button>}{item.status === 'dismissed' && admin && <button className="button ghost" disabled={busy} onClick={() => void reopen()}>Reabrir</button>}</div></footer></article>;
}

function ExternalLegislatorResult({ item, locals, call, reload, notify, refresh, canImport }: { item: ExternalLegislatorSearchItem; locals: Legislator[]; call: AdminProps['call']; reload: () => Promise<void>; notify: (value: string) => void; refresh: () => Promise<void>; canImport: boolean }) {
  const [target, setTarget] = useState(item.link?.localEntityId || (item.possibleMatches.length ? '' : 'new'));
  const [fields, setFields] = useState<LegislatorImportField[]>(['fullName', 'district', ...(item.record.party ? ['party' as const] : []), 'bloc', 'mandateStart', 'mandateEnd']); const [busy, setBusy] = useState(false);
  const creating = target === 'new'; const targetLocal = !creating ? locals.find((local) => local.id === target) : null;
  const options: Array<{ id: LegislatorImportField; label: string; value: string }> = [
    { id: 'fullName', label: 'Nombre', value: item.record.fullName }, { id: 'district', label: 'Distrito', value: item.record.district }, ...(item.record.party ? [{ id: 'party' as const, label: 'Partido o alianza', value: item.record.party }] : []), { id: 'bloc', label: 'Bloque', value: item.record.currentBloc || 'Sin bloque' },
    { id: 'mandateStart', label: 'Inicio', value: item.record.mandateStart }, { id: 'mandateEnd', label: 'Fin', value: item.record.mandateEnd },
  ];
  function toggle(field: LegislatorImportField, checked: boolean) { setFields((current) => checked ? [...new Set([...current, field])] : current.filter((itemField) => itemField !== field)); }
  async function apply() { if (!canImport) return; setBusy(true); try { await call('/v1/manage/integrations/legislators/import', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ sourceId: item.record.sourceId, externalId: item.record.externalId, localLegislatorId: !creating && target ? target : null, createNew: creating, fields }) }); await reload(); notify('Datos oficiales aplicados a un perfil privado. No se publicó ningún cambio.'); await refresh(); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos importar el perfil.'); } finally { setBusy(false); } }
  return <article className="external-result"><div className="external-result-heading"><div><strong>{item.record.fullName}</strong><span>{item.record.sourceId === 'senate-legislators' ? 'Senado' : 'Diputados'} · {item.record.externalId} · {item.record.district}</span></div>{item.link && <span className="status-pill">Vinculado</span>}</div><div className="external-fields">{options.map((option) => <label key={option.id}><input type="checkbox" checked={fields.includes(option.id)} disabled={creating && option.id === 'fullName'} onChange={(event) => toggle(option.id, event.target.checked)} /><span><small>{option.label}</small>{option.value}</span></label>)}</div>{!item.link && <Field label="Destino en Quórum"><select value={target} onChange={(event) => { const value = event.target.value; setTarget(value); if (value === 'new' && !fields.includes('fullName')) setFields([...fields, 'fullName']); }}><option value="">Revisar coincidencias antes de continuar</option><option value="new">Crear perfil privado nuevo</option>{locals.map((local) => <option value={local.id} key={local.id}>{local.fullName} · {local.district || 'Sin distrito'}{local.published ? ' · público' : ''}</option>)}</select></Field>}{item.possibleMatches.length > 0 && !item.link && <p className="match-warning">Encontramos {item.possibleMatches.length} perfil(es) parecido(s). Elegí el destino para evitar duplicados.</p>}{targetLocal?.published && <p className="match-warning">El perfil elegido ya es público. Esta fase no lo sobrescribe automáticamente.</p>}<div className="external-result-actions"><a href={item.record.officialUrl || '#'} target="_blank" rel="noreferrer">Ver ficha oficial ↗</a><button className="button primary" disabled={!canImport || busy || !target || !fields.length || targetLocal?.published} onClick={apply}>{busy ? 'Aplicando…' : canImport ? (item.link ? 'Actualizar perfil privado' : 'Importar selección') : 'Importación en observación'}</button></div></article>;
}

function Glossary({ data, call, reload, notify }: AdminProps) {
  type GlossaryForm = { term: string; slug: string; shortDefinition: string; definition: string; definitionFormat: 'plain' | 'markdown'; aliases: string[]; inlineEnabled: boolean; published: boolean; references: Source[] };
  const empty: GlossaryForm = { term: '', slug: '', shortDefinition: '', definition: '', definitionFormat: 'markdown', aliases: [], inlineEnabled: false, published: false, references: [] };
  const [selectedId, setSelectedId] = useState(''); const [form, setForm] = useState<GlossaryForm>(empty); const [baseline, setBaseline] = useState(JSON.stringify(empty));
  const [query, setQuery] = useState(''); const [visibility, setVisibility] = useState(''); const [inline, setInline] = useState(''); const [pendingId, setPendingId] = useState<string | null>(null); const [busy, setBusy] = useState(false); const [saveFeedback, setSaveFeedback] = useState<{ kind: 'success' | 'error'; text: string } | null>(null);
  const dirty = JSON.stringify(form) !== baseline;
  const filtered = data.glossary.filter((item) => (!query || searchKey(`${item.term} ${(item.aliases || []).join(' ')}`).includes(searchKey(query))) && (!visibility || (visibility === 'public' ? item.published : !item.published)) && (!inline || (inline === 'enabled' ? item.inlineEnabled : !item.inlineEnabled)));
  const selected = data.glossary.find((item) => item.id === selectedId) || null;
  const matchingProjects = selected ? data.projects.filter((project) => glossaryTermAppearsInTexts(selected, [project.summary, project.impact, ...project.updates.map((item) => item.body)])) : [];
  function formFor(item: GlossaryTerm): GlossaryForm { return { term: item.term, slug: item.slug, shortDefinition: item.shortDefinition || '', definition: item.definition, definitionFormat: item.definitionFormat || 'plain', aliases: item.aliases || [], inlineEnabled: item.inlineEnabled || false, published: item.published, references: item.references || [] }; }
  function choose(id: string) { if (dirty) { setPendingId(id); return; } load(id); }
  function load(id: string) { const item = data.glossary.find((candidate) => candidate.id === id); const next = item ? formFor(item) : empty; setSelectedId(id); setForm(next); setBaseline(JSON.stringify(next)); setSaveFeedback(null); setPendingId(null); }
  async function save() {
    const updating = Boolean(selectedId);
    setBusy(true); setSaveFeedback(null);
    try {
      const path = updating ? `/v1/manage/glossary/${selectedId}` : '/v1/manage/glossary';
      const response = await call(path, { method: updating ? 'PUT' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) });
      const saved = response.item as GlossaryTerm;
      const savedForm = formFor(saved);
      setSelectedId(saved.id); setForm(savedForm); setBaseline(JSON.stringify(savedForm));
      await reload();
      const text = updating ? 'Término actualizado y guardado correctamente.' : 'Término creado y guardado correctamente.';
      setSaveFeedback({ kind: 'success', text }); notify(text);
    } catch (error) {
      const text = error instanceof Error ? error.message : 'No pudimos guardar el término.';
      setSaveFeedback({ kind: 'error', text }); notify(text);
    } finally { setBusy(false); }
  }
  return <><div className="admin-two glossary-admin"><section className="admin-panel"><div className="panel-title"><div><h2>Términos</h2><p>Prepará definiciones breves y alias antes de activarlos dentro del texto.</p></div><button className="button ghost" type="button" onClick={() => choose('')}>Nuevo término</button></div><div className="profile-filters"><Field label="Buscar"><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} /></Field><Field label="Estado"><select value={visibility} onChange={(event) => setVisibility(event.target.value)}><option value="">Todos</option><option value="public">Públicos</option><option value="private">Privados</option></select></Field><Field label="Texto contextual"><select value={inline} onChange={(event) => setInline(event.target.value)}><option value="">Todos</option><option value="enabled">Activos</option><option value="pending">Pendientes</option></select></Field></div><div className="table-list glossary-list">{filtered.map((item) => <div className={`glossary-list-row${selectedId === item.id ? ' selected' : ''}`} key={item.id}><div className="glossary-list-summary"><strong>{item.term}</strong><span>{item.published ? 'Público' : 'Privado'} · {item.inlineEnabled ? 'Detección automática activa' : 'Pendiente de preparar'}</span></div><button type="button" className="button ghost glossary-edit-button" aria-label={`Editar término ${item.term}`} aria-pressed={selectedId === item.id} onClick={() => choose(item.id)}>{selectedId === item.id ? 'Editando' : 'Editar'}</button></div>)}{filtered.length === 0 && <p className="empty-list-message">No encontramos términos con estos filtros.</p>}</div></section><section className="admin-panel editor-form glossary-editor-form"><div className="panel-title"><div><h2>{selected ? `Editar ${selected.term}` : 'Nuevo término'}</h2><p>{dirty ? 'Hay cambios sin guardar.' : 'No hay cambios pendientes.'}</p></div></div><Field label="Término"><input value={form.term} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, term: event.target.value, slug: selectedId ? form.slug : slugify(event.target.value) }); }} /></Field><Field label="Slug"><input value={form.slug} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, slug: slugify(event.target.value) }); }} /></Field><Field label={`Definición breve (${form.shortDefinition.length}/320)`}><textarea maxLength={320} value={form.shortDefinition} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, shortDefinition: event.target.value }); }} /></Field><section className="advanced-editor-field"><div className="advanced-editor-heading"><div><strong>Definición completa</strong><span>Editor avanzado: títulos, enlaces, listas, citas, tablas e imágenes.</span></div></div><QuorumRichTextEditor value={form.definition} onChange={(definition) => { setSaveFeedback(null); setForm((current) => ({ ...current, definition, definitionFormat: 'markdown' })); }} onUploadImage={(file) => uploadRichImage(call, file)} placeholder="Desarrollá una entrada completa para este término…" /></section><Field label="Alias, uno por línea"><textarea value={form.aliases.join('\n')} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, aliases: event.target.value.split(/\r?\n|,/).map((item) => item.trim()).filter(Boolean) }); }} /></Field><label className="check-row"><input type="checkbox" checked={form.inlineEnabled} disabled={!form.shortDefinition.trim()} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, inlineEnabled: event.target.checked }); }} /><span>Detectar automáticamente cuando el término o sus alias aparezcan en un proyecto</span></label><label className="check-row"><input type="checkbox" checked={form.published} onChange={(event) => { setSaveFeedback(null); setForm({ ...form, published: event.target.checked }); }} /><span>Publicar definición</span></label>{form.shortDefinition && <div className="glossary-admin-preview"><span>Vista previa</span><strong>{form.term || 'Término'}</strong><p>{form.shortDefinition}</p></div>}{selected && <div className="glossary-usage"><strong>Detección automática</strong><span>{matchingProjects.length} proyecto(s) contienen el término o alguno de sus alias</span>{selected.published && selected.inlineEnabled ? <span>Se mostrará automáticamente en las fichas públicas coincidentes.</span> : <p className="match-warning">Las coincidencias son sólo una vista previa hasta publicar y activar el término.</p>}</div>}{saveFeedback && <p className={`message ${saveFeedback.kind === 'error' ? 'error' : 'success'}`} role={saveFeedback.kind === 'error' ? 'alert' : 'status'}>{saveFeedback.text}</p>}<button className="button primary" disabled={!dirty || busy || !form.term.trim() || !form.definition.trim()} onClick={() => void save()}>{busy ? 'Guardando…' : 'Guardar término'}</button></section></div>{pendingId !== null && <div className="dialog-backdrop" onMouseDown={() => setPendingId(null)}><section className="dialog" role="alertdialog" aria-labelledby="glossary-leave-title" onMouseDown={(event) => event.stopPropagation()}><h2 id="glossary-leave-title">¿Descartar cambios del glosario?</h2><p>Los datos que todavía no guardaste se perderán.</p><div className="dialog-actions"><button className="button ghost" onClick={() => setPendingId(null)}>Seguir editando</button><button className="button danger" onClick={() => load(pendingId)}>Descartar y continuar</button></div></section></div>}</>;
}

function Catalogs({ data, call, reload, notify }: AdminProps) {
  const [form, setForm] = useState({ id: '', kind: 'chamber', label: '', description: '', order: 0, active: true }); async function save() { try { await call('/v1/manage/catalogs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) }); await reload(); notify('Catálogo guardado.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos guardar.'); } }
  return <><section className="admin-panel"><h2>Flujos versionados</h2>{data.workflows.map((flow) => <div className="workflow-admin" key={flow.id}><div><strong>{flow.name} · v{flow.version}</strong><span>{flow.active ? 'Activo' : 'Histórico'}</span></div><ol>{flow.stages.sort((a,b) => a.order-b.order).map((stage) => <li key={stage.id}>{stage.label}{stage.branchFromId ? ` — rama desde ${stage.branchFromId}` : ''}{stage.terminal ? ' — terminal' : ''}</li>)}</ol></div>)}</section><div className="admin-two"><section className="admin-panel"><h2>Catálogos</h2><div className="table-list">{data.catalogs.map((item) => <div key={item.id}><strong>{item.label}</strong><span>{item.kind} · {item.active ? 'Activo' : 'Inactivo'}</span></div>)}</div></section><section className="admin-panel"><h2>Nuevo valor</h2><Field label="Etiqueta"><input value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value, id: slugify(e.target.value) })} /></Field><Field label="Clave estable"><input value={form.id} onChange={(e) => setForm({ ...form, id: slugify(e.target.value) })} /></Field><Field label="Tipo"><select value={form.kind} onChange={(e) => setForm({ ...form, kind: e.target.value })}><option value="chamber">Cámara</option><option value="initiative">Iniciativa</option></select></Field><button className="button primary" onClick={save}>Guardar valor</button></section></div></>;
}

function Followers({ data }: { data: Bootstrap }) { return <section className="admin-panel"><div className="panel-title"><div><h2>Suscripciones</h2><p>Los tokens no son visibles y se guardan con hash.</p></div><span className="status-pill">{data.subscriptions.filter((item) => item.status === 'active').length} activas</span></div><div className="table-list">{data.subscriptions.map((item) => <div key={item.id}><strong>{item.email}</strong><span>{item.status} · {item.projectIds.length} proyecto(s) · consentimiento {new Date(item.consentAt).toLocaleDateString('es-AR')}</span></div>)}</div></section>; }

function Settings({ data, call, reload, notify }: AdminProps) {
  const [form, setForm] = useState(data.settings); const [baseline, setBaseline] = useState(JSON.stringify(data.settings)); const [busy, setBusy] = useState(false); const [feedback, setFeedback] = useState<{ kind: 'success' | 'error'; text: string } | null>(null); const dirty = JSON.stringify(form) !== baseline;
  async function save() { setBusy(true); setFeedback(null); try { const response = await call('/v1/manage/settings', { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) }); const saved = response.item as SiteSettings; setForm(saved); setBaseline(JSON.stringify(saved)); await reload(); setFeedback({ kind: 'success', text: 'Configuración guardada y caché pública invalidada.' }); notify('Configuración guardada.'); } catch (error) { const text = error instanceof Error ? error.message : 'No pudimos guardar.'; setFeedback({ kind: 'error', text }); notify(text); } finally { setBusy(false); } }
  return <div className="settings-stack"><section className="admin-panel editor-form"><h2>Configuración pública</h2><label className="check-row"><input type="checkbox" checked={form.privacyPolicyApproved} onChange={(e) => setForm({ ...form, privacyPolicyApproved: e.target.checked })} /><span>La política de privacidad recibió aprobación institucional</span></label><label className="check-row"><input type="checkbox" checked={form.subscriptionsEnabled} onChange={(e) => setForm({ ...form, subscriptionsEnabled: e.target.checked })} /><span>Habilitar seguimiento por correo (interruptor operativo)</span></label><hr /><label className="check-row"><input type="checkbox" checked={form.electionPortal.enabled} onChange={(e) => setForm({ ...form, electionPortal: { ...form.electionPortal, enabled: e.target.checked } })} /><span>Mostrar bloque electoral</span></label><Field label="Título"><input value={form.electionPortal.title} onChange={(e) => setForm({ ...form, electionPortal: { ...form.electionPortal, title: e.target.value } })} /></Field><Field label="Descripción"><textarea value={form.electionPortal.description} onChange={(e) => setForm({ ...form, electionPortal: { ...form.electionPortal, description: e.target.value } })} /></Field><Field label="URL vigente"><input type="url" value={form.electionPortal.url} onChange={(e) => setForm({ ...form, electionPortal: { ...form.electionPortal, url: e.target.value } })} /></Field></section><section className="admin-panel"><StageExplanationEditor value={form.legislativeStageExplanations} workflows={data.workflows} catalogs={data.catalogs} onChange={(legislativeStageExplanations) => { setFeedback(null); setForm({ ...form, legislativeStageExplanations }); }} /></section><div className="settings-savebar"><div><strong>{dirty ? 'Hay cambios sin guardar' : 'Configuración al día'}</strong><span>{dirty ? 'Los textos públicos no cambiarán hasta que guardes.' : 'La ficha pública está usando esta configuración.'}</span></div>{feedback && <p className={`message ${feedback.kind}`} role={feedback.kind === 'error' ? 'alert' : 'status'}>{feedback.text}</p>}<button className="button primary" disabled={!dirty || busy} onClick={() => void save()}>{busy ? 'Guardando…' : 'Guardar configuración'}</button></div></div>;
}

function Users({ data, call, reload, notify }: AdminProps) {
  const [email, setEmail] = useState(''); const [role, setRole] = useState('quorum_editor'); async function save() { try { await call(`/v1/manage/roles/${encodeURIComponent(email)}`, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ roles: [role], active: true }) }); setEmail(''); await reload(); notify('Acceso asignado.'); } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos asignar acceso.'); } }
  return <div className="admin-two"><section className="admin-panel"><h2>Accesos explícitos</h2><div className="table-list">{data.roles.map((item) => <div key={item.id}><strong>{item.email}</strong><span>{item.roles.join(', ')} · {item.active ? 'Activo' : 'Inactivo'}</span></div>)}</div></section><section className="admin-panel"><h2>Asignar acceso</h2><Field label="Email"><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} /></Field><Field label="Rol"><select value={role} onChange={(e) => setRole(e.target.value)}><option value="quorum_editor">Editor</option><option value="quorum_admin">Administrador</option></select></Field><button className="button primary" onClick={save}>Asignar</button></section></div>;
}

function History({ data, call, reload, notify, admin }: AdminProps & { admin: boolean }) {
  const revisions = [...data.revisions].sort((a,b) => b.createdAt.localeCompare(a.createdAt)); return <section className="admin-panel"><h2>Revisiones publicadas</h2><div className="history-list">{revisions.map((item) => <article key={item.id}><div><strong>Revisión {item.number} · {data.projects.find((project) => project.id === item.projectId)?.title}</strong><span>{new Date(item.createdAt).toLocaleString('es-AR')} · {item.actorEmail}</span><p>{item.changeSummary || 'Sin resumen editorial'} · {item.notifyFollowers ? 'Notificó seguidores' : 'Sin notificación'}</p></div>{admin && <button className="button ghost" onClick={async () => { await call(`/v1/manage/projects/${item.projectId}/revisions/${item.id}/restore`, { method: 'POST' }); await reload(); notify('La revisión se restauró como un borrador nuevo. No se notificará hasta volver a publicar.'); }}>Restaurar como borrador</button>}</article>)}</div></section>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function AdvancedTextField({ label, value, format, onChange, onFormatChange, onUploadImage }: { label: string; value: string; format: 'plain' | 'markdown'; onChange: (value: string) => void; onFormatChange: (value: 'plain' | 'markdown') => void; onUploadImage: (file: File) => Promise<string> }) {
  const [advanced, setAdvanced] = useState(format === 'markdown');
  function enableAdvanced() { onFormatChange('markdown'); setAdvanced(true); }
  return <section className="advanced-editor-field"><div className="advanced-editor-heading"><div><strong>{label}</strong><span>{format === 'markdown' ? 'El contenido se guarda con formato avanzado.' : 'Podés continuar con texto simple o habilitar herramientas avanzadas.'}</span></div><button className="button ghost compact" type="button" aria-pressed={advanced} onClick={() => advanced ? setAdvanced(false) : enableAdvanced()}>{advanced ? 'Ver Markdown' : 'Modo avanzado'}</button></div>{advanced ? <QuorumRichTextEditor value={value} onChange={onChange} onUploadImage={onUploadImage} placeholder={`Escribí ${label.toLocaleLowerCase('es-AR')}…`} ariaLabel={label} /> : <label className="field advanced-plain-field"><span>{format === 'markdown' ? 'Contenido Markdown' : 'Texto simple'}</span><textarea aria-label={label} value={value} onChange={(event) => onChange(event.target.value)} /></label>}</section>;
}
function statusLabel(status: Project['status']) { return ({ draft: 'Borrador', published: 'Publicado', unpublished: 'Despublicado', archived: 'Archivado' })[status]; }
function slugify(value: string) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 120); }
function isHttpUrl(value: string) { try { const url = new URL(value); return url.protocol === 'http:' || url.protocol === 'https:'; } catch { return false; } }
function searchKey(value: string) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function officeLabel(office: Legislator['office']) { return ({ diputado: 'Diputados', senador: 'Senado', otro: 'Otros' })[office]; }
function freshnessLabel(value: IntegrationSource['freshness']) { return ({ fresh: 'Caché vigente', expiring: 'Próxima a vencer', due: 'Revisión vencida', syncing: 'Sincronizando', attention: 'Requiere atención' })[value]; }
function changeTypeLabel(value: LegislatorImportSuggestion['changeType']) { return ({ added: 'Alta oficial', changed: 'Datos modificados', removed: 'Baja oficial' })[value]; }
function changeFieldLabel(value: string) { return ({ fullName: 'Nombre', district: 'Distrito', party: 'Partido o alianza', bloc: 'Bloque', mandateStart: 'Inicio de mandato', mandateEnd: 'Fin de mandato', oathDate: 'Juramento', cessationDate: 'Cese', blocHistory: 'Historial de bloques', officialUrl: 'Ficha oficial' } as Record<string,string>)[value] || value; }
function displayChangeValue(value: unknown) { if (value === null || value === undefined || value === '') return 'Sin dato'; if (Array.isArray(value)) return value.map((item) => typeof item === 'object' ? JSON.stringify(item) : String(item)).join(' · '); return typeof value === 'object' ? JSON.stringify(value) : String(value); }
function hasLegislatorFilters(filters: LegislatorFilters) { return Object.values(filters).some(Boolean); }
function uniqueLegislatorValues(items: Legislator[], field: 'district' | 'party' | 'bloc') {
  return [...new Set(items.map((item) => item[field]).filter((value): value is string => Boolean(value)))].sort((left, right) => left.localeCompare(right, 'es'));
}
function legislatorFacetOptions(items: Legislator[], filters: LegislatorFilters, field: Exclude<keyof LegislatorFilters, 'query'>, candidates: readonly string[]) {
  const scoped = filterLegislators(items, { ...filters, [field]: '' });
  return candidates.map((value) => ({ value, count: scoped.filter((item) => item[field] === value).length }));
}
function filterLegislators(items: Legislator[], filters: LegislatorFilters) {
  const needle = searchKey(filters.query);
  return [...items].filter((item) => {
    const matchesText = !needle || searchKey(`${item.fullName} ${item.party} ${item.bloc} ${item.district}`).includes(needle);
    return matchesText
      && (!filters.office || item.office === filters.office)
      && (!filters.district || item.district === filters.district)
      && (!filters.party || item.party === filters.party)
      && (!filters.bloc || item.bloc === filters.bloc);
  }).sort((left, right) => left.fullName.localeCompare(right.fullName, 'es'));
}
function groupLegislators(items: Legislator[]) {
  const groups: Array<{ key: Legislator['office']; label: string }> = [
    { key: 'diputado', label: 'Diputados' },
    { key: 'senador', label: 'Senado' },
    { key: 'otro', label: 'Otros' },
  ];
  return groups.map((group) => ({ ...group, items: items.filter((item) => item.office === group.key) })).filter((group) => group.items.length > 0);
}
function projectToInput(project: Project): ProjectInput { const { id: _id, status: _status, publishedRevisionId: _revision, publishedAt: _published, updatedAt: _updated, updatedBy: _by, ...input } = project; return input; }
function getPublicationIssues(project: Project, input: ProjectInput, isDirty: boolean, savedChangesPending: boolean, data: Bootstrap) {
  const issues: string[] = [];
  if (isDirty) issues.push('Guardá o descartá los cambios que todavía están sólo en esta pantalla.');
  if (project.status === 'published' && !savedChangesPending) issues.push('No hay cambios guardados respecto de la revisión que ya está publicada.');
  if (!input.docketNumber?.trim()) issues.push('Falta completar el número de expediente.');
  if (!input.entryDate) issues.push('Falta completar la fecha de ingreso.');
  if (!input.originChamberId) issues.push('Falta seleccionar la cámara de origen.');
  else if (!data.catalogs.some((item) => item.id === input.originChamberId && item.active)) issues.push('La cámara seleccionada ya no está activa.');
  if (!input.initiativeTypeId) issues.push('Falta seleccionar el tipo de iniciativa.');
  else if (!data.catalogs.some((item) => item.id === input.initiativeTypeId && item.active)) issues.push('La iniciativa seleccionada ya no está activa.');
  if ((input.summary || '').trim().length < 20) issues.push('El resumen en lenguaje claro debe tener al menos 20 caracteres.');
  if ((input.impact || '').trim().length < 20) issues.push('“¿Cómo me afecta?” debe tener al menos 20 caracteres.');
  const workflow = data.workflows.find((item) => item.id === input.workflowId && item.version === input.workflowVersion);
  if (!workflow?.stages.some((stage) => stage.id === input.currentStageId && stage.active)) issues.push('El flujo o la etapa seleccionada ya no son válidos.');
  return issues;
}
function withoutUpdates(input: ProjectInput) { const { updates: _updates, ...rest } = input; return rest; }
function sameValue(left: unknown, right: unknown) { return JSON.stringify(left) === JSON.stringify(right); }
function formatDateTime(value: string) { return new Date(value).toLocaleString('es-AR', { dateStyle: 'short', timeStyle: 'short' }); }
function emptyProject(workflow?: WorkflowDefinition): ProjectInput { return { title: '', slug: '', workflowId: workflow?.id || 'proceso-legislativo-nacional-v1', workflowVersion: workflow?.version || 1, currentStageId: workflow?.stages.find((item) => !item.branchFromId)?.id || 'mesa-de-entrada', stageExplanationOverrides: [], docketNumber: '', entryDate: null, originChamberId: null, initiativeTypeId: null, summary: '', summaryFormat: 'plain', impact: '', impactFormat: 'plain', authorLegislatorId: null, signatoryIds: [], glossaryTermIds: [], glossaryEnabled: true, glossaryExcludedTermIds: [], glossaryOccurrenceMode: 'all', glossaryExcludedOccurrenceIds: [], documents: [], sources: [], updates: [], featured: false, order: 0 }; }
async function uploadRichImage(call: AdminProps['call'], file: File) { const body = new FormData(); body.append('file', file); const response = await call('/v1/manage/media/images', { method: 'POST', body }); return String(response.item.url || ''); }
